head.b:skin:
  /* ==========================================================================
     GRAVITY ULTRA V16.0 PRO - MASTER CSS (GALAXY THEME) - EDICIÓN METÁLICA | BASE COMPATIBLE V17 SAFE
     ========================================================================== */
  :root {
    --gu-neon: #ff0033;
    --gu-bg: #030303;
    --gu-text: #ffffff;
    --gu-muted: rgba(255, 255, 255, 0.5);
    --gu-glass: rgba(5, 5, 5, 0.25);
    --gu-font-tech: 'Courier New', Courier, monospace;
    --gu-font-main: 'Helvetica Neue', Arial, sans-serif;
    --gu-shadow-color: #000000;
  }

  body { margin: 0; padding: 0; background-color: var(--gu-bg); display: flex; flex-direction: column; align-items: center; min-height: 100vh; overflow-x: hidden; font-family: var(--gu-font-main); position: relative; z-index: 0; }
  #gu-background-video { position: fixed; top: 50%; left: 50%; min-width: 100%; min-height: 100%; width: auto; height: auto; z-index: -2; transform: translateX(-50%) translateY(-50%); object-fit: cover; will-change: transform; }
  body::before { content: ""; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(3, 3, 3, 0.5); z-index: -1; }

  /* MODO IFRAME */
  .gu-is-iframe #gu-creator-zone, .gu-is-iframe .gu-panel-hd-color, .gu-is-iframe .gu-menu-domain, .gu-is-iframe .gu-color-carousel-wrapper { display: none !important; }
  .gu-is-iframe .gu-glass-tubes, .gu-is-iframe .gu-tubes-toggle { display: none !important; }
  .gu-is-iframe body { background: transparent !important; }
  .gu-is-iframe body::before { display: none !important; }
  .gu-is-iframe #gu-background-video { display: none !important; }
  .gu-is-iframe #gravity-ultra-wrapper { margin-top: 0; width: 100%; border-radius: 0; box-shadow: none; aspect-ratio: auto; height: 100vh; }
  .gu-server-status { display: none !important; }
  .gu-is-iframe .gu-category-tabs, .gu-is-iframe .gu-font-nav { display: none !important; }

  /* CONTENEDORES MAESTROS */
  .gu-video-wrapper { position: relative; width: 95%; max-width: 1400px; aspect-ratio: 21 / 9; background: #000; border-radius: 12px; margin-top: 40px; box-shadow: 0 25px 60px rgba(0,0,0,0.9), 0 0 30px var(--gu-neon); overflow: hidden; color: var(--gu-text); user-select: none; transition: box-shadow 0.4s ease; transform: translateZ(0); will-change: transform; }
  .gu-cursor-hidden, .gu-cursor-hidden * { cursor: none !important; }

  /* CAPAS DE VIDEO */
  .gu-layer { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; }
  .gu-bg-lava { opacity: 0.4; filter: contrast(1.3) saturate(1.2); z-index: 1; transition: opacity 0.3s ease; pointer-events: none; }
  .gu-main-video { z-index: 2; background: transparent; cursor: pointer; pointer-events: auto; transition: filter 0.4s ease; }
  .gu-cinematic-tint { z-index: 2; pointer-events: none; opacity: 0; transition: opacity 0.4s ease, background-color 0.4s ease; mix-blend-mode: color; }
  .gu-gradient-shadow { position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: 3; background: radial-gradient(circle at center, transparent 15%, #000 95%); pointer-events: none; }

  /* INTERFAZ HUD */
  .gu-ui-container { position: absolute; top: 0; left: 0; z-index: 10; width: 100%; height: 100%; transition: opacity 0.3s ease; pointer-events: none; }
  .gu-hud { position: absolute; display: flex; align-items: center; gap: 12px; letter-spacing: 2px; transition: transform 0.3s ease, opacity 0.3s ease; }
  .gu-top-left { top: 35px; left: 45px; }
  .gu-top-right { top: 35px; right: 45px; }
  .gu-ui-hidden .gu-top-left { transform: translateX(-30px); opacity: 0; }
  .gu-ui-hidden .gu-top-right { transform: translateX(30px); opacity: 0; }

  .gu-pulse-dot {
    width: 8px;
    height: 8px;
    flex: 0 0 8px;
    background: var(--gu-neon);
    border-radius: 50%;
    opacity: 1;
    transform: translateZ(0) scale(1);
    box-shadow: 0 0 15px var(--gu-neon);
    animation: gu-pulse 1.25s ease-in-out infinite !important;
    animation-play-state: running !important;
    will-change: opacity, transform;
    contain: paint;
  }
  @keyframes gu-pulse {
      0%, 100% {
        opacity: 1;
        transform: translateZ(0) scale(1);
        box-shadow: 0 0 16px var(--gu-neon), 0 0 5px var(--gu-neon);
      }
      50% {
        opacity: 0.16;
        transform: translateZ(0) scale(0.72);
        box-shadow: 0 0 2px var(--gu-neon);
      }
  }

  .gu-text-stack { display: flex; flex-direction: column; font-size: 10px; }
  .gu-t-bold { font-weight: bold; }
  .gu-t-tech { font-family: var(--gu-font-tech); color: var(--gu-muted); font-size: 9px; margin-top: 4px; }

  .gu-movie-info { position: absolute; top: 40%; left: 45px; transform: translateY(-50%); width: auto; max-width: 500px; padding: 0 20px 0 0; transition: opacity 0.3s ease; pointer-events: none; transform-origin: top left; }
  .gu-ui-hidden .gu-movie-info { opacity: 0; }
  .gu-status { font-size: 9px; color: var(--gu-neon); letter-spacing: 4px; display: block; margin-bottom: 8px; transition: color 0.3s; font-weight: bold;}
  .gu-title { font-size: 32px; letter-spacing: 4px; font-weight: 300; margin: 0 0 8px 0; text-transform: uppercase; text-shadow: 0 2px 15px rgba(0,0,0,0.9); line-height: 1.2; word-wrap: break-word; overflow-wrap: break-word; }
  .gu-tags { font-size: 11px; color: var(--gu-muted); letter-spacing: 2px; word-spacing: 2px; text-transform: uppercase; font-family: var(--gu-font-main); font-weight: bold;}

  .gu-font-transitioning { animation: gu-font-slide 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards; }
  @keyframes gu-font-slide {
      0% { opacity: 0; transform: translateX(-20px) scale(0.98); filter: blur(2px); }
      100% { opacity: 1; transform: translateX(0) scale(1); filter: blur(0); }
  }

  .gu-category-tabs { position: absolute; top: 25px; left: 50%; transform: translateX(-50%); display: flex; gap: 12px; z-index: 45; opacity: 0; pointer-events: none; transition: opacity 0.3s ease, transform 0.3s ease; }
  .gu-video-wrapper:hover .gu-category-tabs { opacity: 1; pointer-events: auto; }
  .gu-ui-hidden .gu-category-tabs { opacity: 0 !important; pointer-events: none !important; transform: translate(-50%, -10px); }

  .gu-cat-btn { background: var(--gu-glass); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.15); color: var(--gu-muted); padding: 8px 16px; border-radius: 20px; font-family: var(--gu-font-tech); font-size: 9px; letter-spacing: 2px; cursor: pointer; transition: all 0.3s; text-transform: uppercase; outline: none; box-shadow: 0 5px 15px rgba(0,0,0,0.5); }
  .gu-cat-btn:hover { color: #fff; border-color: rgba(255,255,255,0.5); box-shadow: 0 0 15px rgba(255,255,255,0.2); transform: translateY(-2px); }
  .gu-cat-btn.active { color: var(--gu-neon); border-color: var(--gu-neon); box-shadow: 0 0 20px var(--gu-neon), inset 0 0 8px var(--gu-neon); font-weight: bold; }

  .gu-font-nav { position: absolute; left: 15px; top: 40%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 12px; z-index: 45; opacity: 0; pointer-events: none; transition: opacity 0.3s ease, transform 0.3s ease; }
  .gu-video-wrapper:hover .gu-font-nav { opacity: 1; pointer-events: auto; }
  .gu-ui-hidden .gu-font-nav { opacity: 0 !important; pointer-events: none !important; transform: translate(-10px, -50%); }

  .gu-font-arrow { background: var(--gu-glass); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.15); color: var(--gu-muted); width: 28px; height: 38px; border-radius: 8px; display: flex; justify-content: center; align-items: center; cursor: pointer; transition: all 0.3s; box-shadow: 0 5px 15px rgba(0,0,0,0.5); }
  .gu-font-arrow svg { width: 14px; height: 14px; stroke: currentColor; stroke-width: 2; fill: none; transition: transform 0.3s; }
  .gu-font-arrow:hover { color: var(--gu-neon); border-color: var(--gu-neon); box-shadow: 0 0 20px var(--gu-neon); }
  .gu-font-arrow.up:hover svg { transform: translateY(-4px); }
  .gu-font-arrow.down:hover svg { transform: translateY(4px); }

  #gravity-ultra-wrapper .gu-category-tabs, 
  #gravity-ultra-wrapper .gu-font-nav { display: none !important; }

  .gu-core { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); display: flex; justify-content: center; align-items: center; transition: transform 0.3s ease, opacity 0.3s ease; pointer-events: none;}
  .gu-ui-hidden .gu-core { opacity: 0; transform: translate(-50%, -50%) scale(1.3); }
  .gu-ring { position: absolute; border-radius: 50%; border: 1px solid rgba(255,255,255,0.05); pointer-events: none; }
  .gu-r1 { width: 140px; height: 140px; border-color: var(--gu-neon); box-shadow: 0 0 25px var(--gu-neon) inset; transition: border-color 0.4s, box-shadow 0.4s; }
  .gu-r2 { width: 240px; height: 240px; border-top: 1px solid rgba(255,255,255,0.2); }

  .gu-play-zone { width: 90px; height: 90px; display: flex; justify-content: center; align-items: center; cursor: pointer; z-index: 50; pointer-events: auto; }
  .gu-triangle { width: 0; height: 0; border-top: 15px solid transparent; border-bottom: 15px solid transparent; border-left: 24px solid #fff; margin-left: 8px; transition: transform 0.2s; filter: drop-shadow(0 0 5px rgba(255,255,255,0.5)); pointer-events: none; }
  .gu-play-zone:hover .gu-triangle { transform: scale(1.15); filter: drop-shadow(0 0 15px #fff); }

  .gu-center-clock { position:absolute; top:-90px; font-size:14px; font-family: var(--gu-font-tech); color: var(--gu-muted); pointer-events: none;}
  .gu-center-status { position:absolute; bottom:-90px; letter-spacing:5px; font-family: var(--gu-font-tech); color: var(--gu-muted); pointer-events: none;}

  .gu-footer { position: absolute; bottom: 35px; left: 45px; right: 45px; display: flex; align-items: center; justify-content: space-between; transition: transform 0.3s ease, opacity 0.3s ease; }
  .gu-ui-hidden .gu-footer { transform: translateY(20px); opacity: 0; }
  .gu-time { font-family: var(--gu-font-tech); font-size: 13px; width: 130px; pointer-events: none; }

  .gu-progress-bg { flex-grow: 1; height: 10px; background: rgba(255,255,255,0.15); margin: 0 35px; cursor: pointer; position: relative; pointer-events: auto; border-radius: 5px; z-index: 50; overflow: hidden; transition: height 0.2s; }
  .gu-progress-bg:hover { height: 14px; background: rgba(255,255,255,0.25); }
  .gu-progress-bar { height: 100%; width: 0%; background: var(--gu-neon); box-shadow: 0 0 15px var(--gu-neon); position: absolute; top:0; left:0; pointer-events: none; border-radius: 5px; transition: width 0.1s linear; }

  .gu-quality-label { font-size: 11px; letter-spacing: 2px; text-align: right; font-weight: bold; pointer-events: none; transition: color 0.3s; margin-right: 15px;}

  .gu-vol-container { display: flex; align-items: center; gap: 8px; margin-right: 15px; pointer-events: auto; }
  .gu-vol-btn { cursor: pointer; color: var(--gu-muted); transition: all 0.2s; display: flex; align-items: center; }
  .gu-vol-btn:hover { color: var(--gu-neon); transform: scale(1.1); filter: drop-shadow(0 0 5px var(--gu-neon)); }
  .gu-vol-slider { -webkit-appearance: none; width: 45px; height: 4px; background: rgba(255,255,255,0.2); border-radius: 2px; outline: none; transition: 0.2s; cursor: pointer; }
  .gu-vol-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 10px; height: 10px; border-radius: 50%; background: var(--gu-neon); cursor: pointer; box-shadow: 0 0 8px var(--gu-neon); }
  .gu-vol-slider::-moz-range-thumb { width: 10px; height: 10px; border-radius: 50%; background: var(--gu-neon); cursor: pointer; box-shadow: 0 0 8px var(--gu-neon); }

  .gu-fs-btn { cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.2s; color: var(--gu-muted); pointer-events: auto; z-index: 50; }
  .gu-fs-btn:hover { color: var(--gu-neon); transform: scale(1.15); filter: drop-shadow(0 0 8px var(--gu-neon)); }

  /* ================== PANELES Y FLECHAS RETRÁCTILES ================== */
  .gu-panel-glass { position: absolute; right: 65px; top: 50%; transform: translateY(-50%); width: 230px; background: var(--gu-glass); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 25px; display: flex; flex-direction: column; gap: 15px; z-index: 30; pointer-events: auto; transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94), opacity 0.4s ease !important; }

  .gu-panel-toggle { position: absolute; left: -26px; top: 50%; transform: translateY(-50%); width: 26px; height: 50px; background: rgba(10,10,10,0.5); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.1); border-right: none; border-radius: 8px 0 0 8px; cursor: pointer; display: flex; justify-content: center; align-items: center; z-index: 50; transition: all 0.3s ease; pointer-events: auto; }
  .gu-panel-toggle:hover { background: rgba(255,0,51,0.2); border-color: var(--gu-neon); box-shadow: -2px 0 10px rgba(255,0,51,0.3); }
  .gu-panel-toggle svg { width: 14px; height: 14px; fill: none; stroke: var(--gu-muted); stroke-width: 2; transition: all 0.3s ease; }
  .gu-panel-toggle:hover svg { stroke: var(--gu-neon); }

  .gu-panel-glass.hidden-panel { transform: translate3d(calc(100% + 65px), -50%, 0) !important; opacity: 1 !important; pointer-events: none; }
  .gu-panel-glass.hidden-panel .gu-panel-toggle { left: -91px; pointer-events: auto; }
  .gu-panel-glass.hidden-panel .gu-panel-toggle svg { transform: scaleX(-1); }

  /* MUERTE A LOS FANTASMAS (Al dar Play) */
  .gu-ui-hidden .gu-panel-glass, .gu-ui-hidden .gu-glass-tubes { opacity: 0 !important; pointer-events: none !important; transform: translate3d(30px, -50%, 0) !important; }
  .gu-ui-hidden .gu-panel-toggle, .gu-ui-hidden .gu-tubes-toggle { opacity: 0 !important; pointer-events: none !important; }
  .gu-ui-hidden .gu-corel-panel { opacity: 0 !important; pointer-events: none !important; display: none !important; }

  /* ===================================================================== */

  .gu-panel-hd { font-size: 10px; color: var(--gu-text); font-weight: bold; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 6px; letter-spacing: 2px; }

  .gu-color-carousel-wrapper { display: flex; align-items: center; justify-content: space-between; width: 100%; gap: 5px; }
  .gu-color-row { display: flex; gap: 10px; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; flex-wrap: nowrap; padding: 5px 0; flex-grow: 1; }
  .gu-color-row::-webkit-scrollbar { display: none; } 

  .gu-carousel-arrow { background: transparent; border: none; color: var(--gu-muted); font-size: 16px; cursor: pointer; transition: all 0.3s; padding: 0; font-family: monospace; font-weight: bold; outline: none; }
  .gu-carousel-arrow:hover { color: var(--gu-neon); text-shadow: 0 0 10px var(--gu-neon); transform: scale(1.3); }

  .gu-btn-color { flex-shrink: 0; width: 18px; height: 18px; border-radius: 50%; border: 2px solid transparent; cursor: pointer; transition: all 0.2s; position: relative; }
  .gu-btn-color:hover { transform: scale(1.2); }
  .gu-btn-color.active { box-shadow: 0 0 12px #fff; border-color: #fff; transform: scale(1.1); }

  .gu-btn-infinite { background: conic-gradient(red, yellow, lime, aqua, blue, magenta, red); overflow: hidden; border: 2px solid #fff; }
  .gu-btn-infinite input[type="color"] { position: absolute; top: -10px; left: -10px; width: 200%; height: 200%; opacity: 0; cursor: pointer; z-index: 2; }

  /* ================== MENÚS DELGADOS Y SUTILES ================== */
  .gu-menu-container { display: flex; flex-direction: column; gap: 6px; }
  .gu-menu-item { font-family: var(--gu-font-tech); font-size: 8.5px; color: #fff; cursor: pointer; padding: 4px 6px; background: rgba(0,0,0,0.2); border-radius: 3px; border: 1px solid rgba(255,255,255,0.02); transition: 0.2s; letter-spacing: 1px; display: flex; justify-content: space-between; align-items: center; }
  .gu-menu-item:hover { border-color: var(--gu-neon); color: var(--gu-neon); background: rgba(0,0,0,0.4); }
  .gu-dropdown { display: none; flex-direction: column; gap: 4px; padding-left: 8px; margin-top: 3px; border-left: 2px solid var(--gu-neon); }
  .gu-drop-opt { font-family: var(--gu-font-tech); font-size: 8px; color: var(--gu-muted); cursor: pointer; transition: 0.2s; padding: 2px 0; }
  .gu-drop-opt:hover { color: var(--gu-text); }
  /* ===================================================================== */

  /* ================== NUEVA FLECHA PARA LOS TUBOS ================== */
  .gu-glass-tubes { position: absolute; right: 15px; top: 50%; transform: translateY(-50%); display: flex; gap: 12px; z-index: 40; pointer-events: auto; transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94), opacity 0.4s ease; }

  .gu-tubes-toggle { position: absolute; right: calc(100% + 5px); top: 50%; transform: translateY(-50%); width: 22px; height: 40px; background: rgba(10,10,10,0.5); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.1); border-right: none; border-radius: 6px 0 0 6px; cursor: pointer; display: flex; justify-content: center; align-items: center; z-index: 50; transition: all 0.3s ease; pointer-events: auto; }
  .gu-tubes-toggle:hover { background: rgba(255,0,51,0.2); border-color: var(--gu-neon); }
  .gu-tubes-toggle svg { width: 12px; height: 12px; fill: none; stroke: var(--gu-muted); stroke-width: 2; transition: all 0.3s ease; }
  .gu-tubes-toggle:hover svg { stroke: var(--gu-neon); }

  .gu-glass-tubes.hidden-tubes { transform: translate3d(calc(100% + 15px), -50%, 0) !important; opacity: 1 !important; pointer-events: none; }
  .gu-glass-tubes.hidden-tubes .gu-tubes-toggle { right: 100%; pointer-events: auto; border-right: 1px solid rgba(255,255,255,0.1); border-radius: 6px; }
  .gu-glass-tubes.hidden-tubes .gu-tubes-toggle svg { transform: scaleX(-1); }
  /* ===================================================================== */

  .gu-tube { width: 26px; height: 220px; background: rgba(255,255,255,0.05); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border: 1px solid rgba(255,255,255,0.15); border-radius: 15px; display: flex; flex-direction: column; align-items: center; padding: 10px 0; box-shadow: inset 0 0 15px rgba(0,0,0,0.8), 0 0 10px rgba(0,0,0,0.5); overflow-y: auto; scrollbar-width: none; }
  .gu-tube::-webkit-scrollbar { display: none; }

  .gu-thermometer-wrapper { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
  .gu-thermometer { appearance: none; -webkit-appearance: none; width: 180px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; outline: none; transform: rotate(-90deg); }
  .gu-thermometer::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; border-radius: 50%; background: var(--gu-neon); cursor: pointer; box-shadow: 0 0 12px var(--gu-neon); transition: transform 0.2s; }
  .gu-thermometer::-webkit-slider-thumb:hover { transform: scale(1.3); }

  .gu-cinematic-dot { width: 14px; height: 14px; border-radius: 50%; margin-bottom: 10px; flex-shrink: 0; cursor: pointer; border: 1px solid rgba(255,255,255,0.3); transition: transform 0.2s, border-color 0.2s; box-shadow: inset 0 0 5px rgba(0,0,0,0.5); }
  .gu-cinematic-dot:hover { transform: scale(1.3); border-color: #fff; }
  .gu-cinematic-dot.active { border: 2px solid #fff; box-shadow: 0 0 10px rgba(255,255,255,0.8); transform: scale(1.2); }

  /* ZONA DE CREADORES */
  #gu-creator-zone { width: 95%; max-width: 1400px; margin-top: 40px; margin-bottom: 150px; border-radius: 12px; position: relative; box-shadow: 0 15px 40px rgba(0,0,0,0.9); border: 1px solid rgba(255,255,255,0.05); color: #fff; background: transparent; }
  .gu-cz-overlay { position: absolute; top:0; left:0; width:100%; height:100%; background: linear-gradient(135deg, rgba(15,15,15,0.4) 0%, rgba(5,5,5,0.5) 100%); backdrop-filter: blur(5px); z-index: 1; border-radius: 12px; }
  .gu-cz-content { position: relative; z-index: 2; display: flex; flex-direction: column; gap: 20px; padding: 40px; }
  .gu-cz-title { font-size: 14px; letter-spacing: 4px; color: var(--gu-text); font-weight: bold; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 15px; margin:0;}
  .gu-cz-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 30px; }
  .gu-cz-col { display: flex; flex-direction: column; gap: 8px;}
  .gu-cz-label { font-size: 10px; color: var(--gu-muted); letter-spacing: 2px; text-transform: uppercase; font-weight: bold; }

  .gu-cz-input, .gu-cz-select { background: rgba(0,0,0,0.6); border: 1px solid rgba(255,255,255,0.15); color: #fff; padding: 12px; border-radius: 6px; font-family: var(--gu-font-tech); outline: none; transition: 0.3s; width: 100%; box-sizing: border-box;}
  .gu-cz-input:focus, .gu-cz-select:focus { border-color: var(--gu-neon); box-shadow: 0 0 10px rgba(255,0,51,0.3); background: rgba(0,0,0,0.9); }
  .gu-cz-btn-add { background: transparent; color: var(--gu-neon); border: 1px dashed rgba(255,0,51,0.5); padding: 8px 15px; border-radius: 4px; font-size: 9px; letter-spacing: 2px; cursor: pointer; align-self: flex-start; margin-top: 5px; transition: 0.3s;}
  .gu-cz-btn-add:hover { background: rgba(255,0,51,0.1); border-style: solid; box-shadow: 0 0 10px rgba(255,0,51,0.3); }
  .gu-backup-link { display: none; margin-top: 5px; position: relative; animation: guFadeIn 0.3s ease; }
  .gu-backup-link.visible { display: block; }
  @keyframes guFadeIn { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }

  .gu-cz-btn-gen { background: transparent; color: #fff; border: 1px solid var(--gu-muted); padding: 15px 30px; border-radius: 6px; font-weight: bold; letter-spacing: 3px; cursor: pointer; transition: all 0.3s; align-self: flex-start; margin-top: 10px;}
  .gu-cz-btn-gen:hover { border-color: var(--gu-neon); background: rgba(255,0,51,0.15); box-shadow: 0 0 20px rgba(255,0,51,0.4); color: var(--gu-neon); }
  .gu-cz-code-box { background: rgba(0,0,0,0.95); border: 1px solid rgba(255,255,255,0.1); color: #00ffcc; padding: 15px; border-radius: 6px; font-family: monospace; height: 120px; resize: none; line-height: 1.5; font-size: 11px; width: 100%; box-sizing: border-box;}
  .gu-poster-preview { width: 120px; height: 180px; border-radius: 6px; background: #111; border: 1px solid rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; font-size: 10px; color: var(--gu-muted); text-align: center; overflow: hidden; margin-top: 10px; transition: all 0.3s;}
  .gu-poster-preview img { width: 100%; height: 100%; object-fit: cover; display: none; }
  .gu-poster-horizontal { width: 320px !important; height: 180px !important; }

  /* ======================================================================
     V24 TMDB VISUAL SELECTOR PRO — SOLO MÓDULO TMDB DEL CREADOR
     ====================================================================== */
  .gu-tmdb-visual-grid{
    display:grid;
    grid-template-columns:minmax(155px,190px) minmax(300px,1fr);
    gap:26px;
    align-items:start;
    margin-top:12px;
  }
  .gu-tmdb-visual-card{
    position:relative;
    min-width:0;
    padding:13px;
    border:1px solid rgba(255,255,255,.09);
    border-radius:12px;
    background:linear-gradient(145deg,rgba(255,255,255,.025),rgba(0,0,0,.12));
    box-shadow:inset 0 0 0 1px rgba(0,0,0,.18);
  }
  .gu-tmdb-visual-title{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:8px;
    margin-bottom:10px;
    color:rgba(255,255,255,.66);
    font-size:8px;
    font-weight:800;
    letter-spacing:1.5px;
    text-transform:uppercase;
  }
  .gu-tmdb-stage{
    position:relative;
    display:flex;
    align-items:center;
    justify-content:center;
    gap:7px;
    min-width:0;
  }
  .gu-tmdb-frame{
    position:relative;
    overflow:hidden;
    background:#08090b;
    border:1px solid rgba(255,255,255,.12);
    box-shadow:0 14px 32px rgba(0,0,0,.28);
  }
  .gu-tmdb-frame.vertical{
    width:120px;
    height:180px;
    border-radius:7px;
  }
  .gu-tmdb-frame.horizontal{
    width:min(100%,360px);
    aspect-ratio:16/9;
    border-radius:8px;
  }
  .gu-tmdb-frame img{
    display:none;
    width:100%;
    height:100%;
    object-fit:cover;
  }
  .gu-tmdb-empty{
    position:absolute;
    inset:0;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:12px;
    text-align:center;
    color:rgba(255,255,255,.32);
    font-size:8px;
    letter-spacing:1.4px;
    line-height:1.5;
  }
  .gu-tmdb-nav,
  .gu-tmdb-lock{
    appearance:none;
    -webkit-appearance:none;
    display:flex;
    align-items:center;
    justify-content:center;
    cursor:pointer;
    color:#EAF7FF;
    background:rgba(5,8,11,.18);
    border:1px solid rgba(234,247,255,.10);
    transition:
      border-color .2s ease,
      box-shadow .2s ease,
      background .2s ease,
      transform .16s ease,
      opacity .2s ease;
    backdrop-filter:blur(7px);
    -webkit-backdrop-filter:blur(7px);
  }
  .gu-tmdb-nav{
    width:27px;
    height:42px;
    flex:0 0 27px;
    border-radius:9px;
    font-size:23px;
    line-height:1;
    font-family:Arial,sans-serif;
    font-weight:300;
  }
  .gu-tmdb-nav:hover,
  .gu-tmdb-lock:hover,
  .gu-tmdb-lock.locked{
    border-color:var(--gu-neon);
    background:color-mix(in srgb,var(--gu-neon) 7%,rgba(5,8,11,.65));
    box-shadow:
      0 0 13px color-mix(in srgb,var(--gu-neon) 30%,transparent),
      inset 0 0 11px color-mix(in srgb,var(--gu-neon) 8%,transparent);
  }
  .gu-tmdb-nav:active,
  .gu-tmdb-lock:active{ transform:scale(.94); }
  .gu-tmdb-nav:disabled{
    cursor:default;
    opacity:.25;
    border-color:rgba(255,255,255,.08);
    box-shadow:none;
  }
  .gu-tmdb-lock{
    width:27px;
    height:27px;
    flex:0 0 27px;
    border-radius:8px;
    padding:0;
  }
  .gu-tmdb-lock svg{width:14px;height:14px;display:block}
  .gu-tmdb-lock.locked{color:var(--gu-neon)}
  .gu-tmdb-count{
    display:block;
    margin-top:8px;
    color:rgba(255,255,255,.38);
    font-size:8px;
    letter-spacing:1.4px;
    text-align:center;
    text-transform:uppercase;
  }
  .gu-tmdb-hint{
    display:block;
    margin-top:8px;
    color:rgba(255,255,255,.28);
    font-size:7px;
    letter-spacing:1.05px;
    line-height:1.45;
    text-align:center;
    text-transform:uppercase;
  }
  .gu-tmdb-hidden-field{display:none !important}

  /* ======================================================================
     V36 SMART ART LIBRARY — búsqueda por nombre + fuente externa validada
     Capa no destructiva: conserva ID TMDB, galería, bloqueo y legacy URL.
     ====================================================================== */
  .gu-art-library{
    margin:0 0 16px;padding:14px;border:1px solid rgba(255,255,255,.09);border-radius:12px;
    background:linear-gradient(145deg,rgba(255,255,255,.025),rgba(0,0,0,.12));
  }
  .gu-art-library-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}
  .gu-art-library-title{color:#fff;font:800 9px/1.3 var(--gu-font-main);letter-spacing:1.6px;text-transform:uppercase}
  .gu-art-library-badge{padding:5px 8px;border:1px solid color-mix(in srgb,var(--gu-neon) 38%,rgba(255,255,255,.08));border-radius:999px;color:var(--gu-neon);font:700 7px/1 var(--gu-font-tech);letter-spacing:1.2px;text-transform:uppercase}
  .gu-art-library-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
  .gu-art-tool{min-width:0;padding:12px;border:1px solid rgba(255,255,255,.07);border-radius:10px;background:rgba(0,0,0,.16)}
  .gu-art-tool-label{display:block;margin-bottom:8px;color:rgba(255,255,255,.58);font:800 8px/1.3 var(--gu-font-tech);letter-spacing:1.25px;text-transform:uppercase}
  .gu-art-inline{display:flex;gap:7px;align-items:stretch}
  .gu-art-inline + .gu-art-inline{margin-top:7px}
  .gu-art-inline .gu-cz-input,.gu-art-inline .gu-cz-select{min-width:0;margin:0;padding:10px;font-size:10px}
  .gu-art-inline .gu-cz-select{flex:0 0 155px}
  .gu-art-btn{appearance:none;-webkit-appearance:none;flex:0 0 auto;padding:0 13px;border:1px solid rgba(255,255,255,.13);border-radius:7px;background:rgba(255,255,255,.03);color:#fff;cursor:pointer;font:800 8px/1 var(--gu-font-tech);letter-spacing:1.2px;text-transform:uppercase;transition:.2s ease}
  .gu-art-btn:hover,.gu-art-btn:focus-visible{border-color:var(--gu-neon);color:var(--gu-neon);box-shadow:0 0 13px color-mix(in srgb,var(--gu-neon) 24%,transparent);outline:none}
  .gu-art-btn.primary{border-color:color-mix(in srgb,var(--gu-neon) 52%,rgba(255,255,255,.10));background:color-mix(in srgb,var(--gu-neon) 9%,rgba(0,0,0,.2));color:var(--gu-neon)}
  .gu-art-status{min-height:14px;margin-top:8px;color:rgba(255,255,255,.38);font:700 7.5px/1.45 var(--gu-font-tech);letter-spacing:.85px;text-transform:uppercase}
  .gu-art-status.ok{color:#58e7ad}.gu-art-status.warn{color:#ffd166}.gu-art-status.error{color:#ff667d}
  .gu-art-results{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:10px}
  .gu-art-result{appearance:none;-webkit-appearance:none;display:grid;grid-template-columns:44px minmax(0,1fr);gap:8px;align-items:center;width:100%;min-width:0;padding:7px;border:1px solid rgba(255,255,255,.08);border-radius:9px;background:rgba(0,0,0,.24);color:#fff;text-align:left;cursor:pointer;transition:.2s ease}
  .gu-art-result:hover,.gu-art-result:focus-visible{border-color:var(--gu-neon);background:color-mix(in srgb,var(--gu-neon) 5%,rgba(0,0,0,.3));outline:none}
  .gu-art-result img{width:44px;height:64px;object-fit:cover;border-radius:5px;background:#08090b}
  .gu-art-result-copy{min-width:0}
  .gu-art-result-title{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#fff;font:800 8px/1.25 var(--gu-font-main)}
  .gu-art-result-meta{display:block;margin-top:4px;color:rgba(255,255,255,.40);font:700 7px/1.2 var(--gu-font-tech);letter-spacing:.6px;text-transform:uppercase}
  .gu-art-advanced{display:flex;align-items:end;gap:8px;margin-top:12px;padding-top:11px;border-top:1px solid rgba(255,255,255,.07)}
  .gu-art-advanced > div{flex:1;min-width:0}
  .gu-art-advanced .gu-cz-input{margin:0}
  .gu-media-upload-trigger{position:absolute;left:50%;bottom:8px;z-index:5;transform:translateX(-50%);max-width:calc(100% - 16px);padding:7px 10px;border:1px solid rgba(255,255,255,.14);border-radius:7px;background:rgba(3,5,8,.74);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);color:#fff;cursor:pointer;font:800 7px/1 var(--gu-font-tech);letter-spacing:1.05px;white-space:nowrap;text-transform:uppercase;transition:.2s ease}
  .gu-media-upload-trigger:hover,.gu-media-upload-trigger:focus-visible{border-color:var(--gu-neon);color:var(--gu-neon);box-shadow:0 0 12px color-mix(in srgb,var(--gu-neon) 25%,transparent);outline:none}
  .gu-media-upload-trigger svg{width:11px;height:11px;margin-right:5px;vertical-align:-2px}
  .gu-local-preview-note{display:none;margin-top:7px;color:#ffd166;font:700 7px/1.4 var(--gu-font-tech);letter-spacing:.8px;text-align:center;text-transform:uppercase}
  .gu-local-preview-note.visible{display:block}

  @media(max-width:900px){
    .gu-tmdb-visual-grid{grid-template-columns:1fr;gap:14px}
    .gu-tmdb-frame.horizontal{width:min(100%,420px)}
    .gu-art-library-grid{grid-template-columns:1fr}
    .gu-art-results{grid-template-columns:repeat(2,minmax(0,1fr))}
    .gu-art-advanced{align-items:stretch;flex-direction:column}
  }
  @media(max-width:560px){
    .gu-art-inline{flex-wrap:wrap}
    .gu-art-inline .gu-cz-select{flex:1 1 130px}
    .gu-art-inline .gu-cz-input{flex:1 1 100%}
    .gu-art-btn{min-height:38px;flex:1 1 auto}
    .gu-art-results{grid-template-columns:1fr}
  }


  /* EMULADORES */
  .gu-emul-mobile { max-width: 380px !important; margin: 0 auto !important; aspect-ratio: 16/9 !important; border-radius: 24px !important; border: 4px solid #222 !important; box-shadow: 0 10px 30px rgba(0,0,0,0.8), 0 0 15px var(--gu-neon) !important; overflow: visible !important; transform: translateX(-50px); }
  .gu-emul-mobile .gu-layer, .gu-emul-mobile .gu-gradient-shadow { border-radius: 18px !important; }
  .gu-emul-mobile .gu-top-left { top: 15px; left: 15px; }
  .gu-emul-mobile .gu-top-right { top: 15px; right: 15px; }
  .gu-emul-mobile .gu-movie-info { left: 40px; width: 45%; max-width: 160px; top: 50%; transform: translateY(-50%); white-space: normal; } 
  .gu-emul-mobile .gu-title { font-size: 13px; letter-spacing: 1px; margin-bottom: 4px; line-height: 1.2; overflow-wrap: break-word; white-space: normal; }
  .gu-emul-mobile .gu-tags { font-size: 8px; line-height: 1.3; letter-spacing: 1px; display: block; overflow-wrap: break-word; white-space: normal; } 
  .gu-emul-mobile .gu-r1 { width: 70px; height: 70px; border-width: 1px; }
  .gu-emul-mobile .gu-r2 { width: 120px; height: 120px; }
  .gu-emul-mobile .gu-play-zone { width: 60px; height: 60px; }
  .gu-emul-mobile .gu-triangle { border-top: 10px solid transparent; border-bottom: 10px solid transparent; border-left: 16px solid #fff; margin-left: 6px; }
  .gu-emul-mobile .gu-center-clock, .gu-emul-mobile .gu-center-status { display: none; }
  .gu-emul-mobile .gu-footer { bottom: 15px; left: 15px; right: 15px; flex-wrap: wrap; }
  .gu-emul-mobile .gu-time { width: auto; font-size: 10px; margin-bottom: 8px; }
  .gu-emul-mobile .gu-progress-bg { margin: 0 0 8px 0; width: 100%; order: -1; }
  .gu-emul-mobile .gu-panel-glass { right: -210px !important; padding: 15px; width: 180px; background: rgba(15,15,15,0.9); border: 1px solid rgba(255,255,255,0.1); box-shadow: 10px 10px 30px rgba(0,0,0,0.8); }
  .gu-emul-mobile .gu-panel-hd { font-size: 9px; padding-bottom: 4px; }
  .gu-emul-mobile .gu-menu-item { font-size: 8px; padding: 4px 6px; }
  .gu-emul-mobile .gu-btn-color { width: 16px; height: 16px; }
  .gu-emul-mobile .gu-glass-tubes { right: -270px !important; gap: 10px; transform: translateY(-50%) scale(0.85); transform-origin: center left; }
  .gu-emul-mobile .gu-category-tabs { top: 50%; left: -135px; transform: translateY(-50%) scale(0.85); width: max-content; flex-direction: column; gap: 12px; opacity: 1 !important; pointer-events: auto !important; }
  .gu-emul-mobile .gu-font-nav { top: 50%; left: -180px; transform: translateY(-50%) scale(0.9); opacity: 1 !important; pointer-events: auto !important; flex-direction: column; gap: 10px; }

  .gu-emul-tv { max-width: 100% !important; margin: 0 auto !important; aspect-ratio: 21/9 !important; border-radius: 8px !important; border: 2px solid #111 !important; box-shadow: 0 20px 50px rgba(0,0,0,0.9), 0 0 40px var(--gu-neon) !important;}
  .gu-emul-tv .gu-title { font-size: 42px; letter-spacing: 5px; margin-bottom: 12px; }
  .gu-emul-tv .gu-tags { font-size: 12px; letter-spacing: 4px; }
  .gu-emul-tv .gu-r1 { width: 160px; height: 160px; border-width: 2px; }
  .gu-emul-tv .gu-r2 { width: 300px; height: 300px; border-top-width: 2px; }
  .gu-emul-tv .gu-play-zone { width: 110px; height: 110px; }
  .gu-emul-tv .gu-triangle { border-top: 18px solid transparent; border-bottom: 18px solid transparent; border-left: 28px solid #fff; margin-left: 8px; }
  .gu-emul-tv .gu-time { font-size: 16px; width: 150px; }
  .gu-emul-tv .gu-quality-label { font-size: 13px; }
  .gu-emul-tv .gu-panel-glass { right: 70px; width: 280px; padding: 30px; }
  .gu-emul-tv .gu-glass-tubes { right: 20px; gap: 14px; }
  .gu-emul-tv .gu-tube { width: 28px; height: 260px; }

