      #gravity-ultra-wrapper:not(.gu-emul-mobile):not(.gu-emul-tv) .gu-time, 
      #gu-live-preview-wrapper:not(.gu-emul-mobile):not(.gu-emul-tv) .gu-time { width: auto; font-size: 11px; margin-bottom: 10px; }
