      #gu-live-preview-wrapper:not(.gu-emul-mobile):not(.gu-emul-tv) .gu-tube { width: 30px; height: 280px; }
  }

  /* ==========================================================================
     V16 PRO - CAPA FANTASMA Y HERRAMIENTAS MÁGICAS (SOLO EMULADORES)
     ========================================================================== */

  .gu-ghost-edit-btn { background: rgba(0,0,0,0.6); border: 1px solid rgba(255,255,255,0.2); color: var(--gu-muted); border-radius: 20px; padding: 6px 12px; font-size: 9px; font-family: var(--gu-font-tech); cursor: pointer; transition: all 0.3s; pointer-events: auto; letter-spacing: 1px; display: flex; align-items: center; gap: 5px; backdrop-filter: blur(5px); margin-left: 15px; outline: none; }
  .gu-ghost-edit-btn:hover { color: #00ffcc; border-color: #00ffcc; background: rgba(0,255,204,0.1); box-shadow: 0 0 10px rgba(0,255,204,0.3); }
  .gu-ghost-edit-btn.active { background: rgba(255,0,51,0.2); color: #ff0033; border-color: #ff0033; }

  .gu-corel-panel { position: absolute; top: 70px; right: 45px; background: rgba(10,10,10,0.95); border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; padding: 12px; display: none; flex-direction: column; gap: 10px; z-index: 100; pointer-events: auto; box-shadow: 0 10px 30px rgba(0,0,0,0.9), 0 0 15px rgba(0,255,204,0.2); backdrop-filter: blur(10px); width: 220px; transition: opacity 0.3s ease; }
  .gu-corel-panel.visible { display: flex; animation: guFadeIn 0.3s ease; }

  .gu-corel-title { font-size: 9px; color: var(--gu-muted); letter-spacing: 2px; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 6px; text-align: center; margin: 0; font-family: var(--gu-font-main); font-weight: bold;}
  .gu-corel-row { display: flex; align-items: center; justify-content: space-between; gap: 5px; margin: 0; }
  .gu-corel-label { font-size: 9px; font-family: var(--gu-font-tech); color: #fff; margin: 0; flex-grow: 1; }

  .gu-corel-color-picker { -webkit-appearance: none; width: 24px; height: 24px; border: none; border-radius: 50%; background: transparent; cursor: pointer; padding: 0; overflow: hidden; }
  .gu-corel-color-picker::-webkit-color-swatch-wrapper { padding: 0; }
  .gu-corel-color-picker::-webkit-color-swatch { border: 1px solid rgba(255,255,255,0.5); border-radius: 50%; }

  .gu-corel-select { background: #000; border: 1px solid rgba(255,255,255,0.2); color: #fff; font-size: 9px; padding: 6px; border-radius: 4px; outline: none; cursor: pointer; font-family: var(--gu-font-tech); width: 100%; box-sizing: border-box; }

  .gu-editing-box { border: 1px dashed rgba(0,255,204,0.5) !important; cursor: move !important; background: rgba(0,0,0,0.3) !important; box-shadow: 0 0 15px rgba(0,255,204,0.2) !important; pointer-events: auto; border-radius: 4px; display: inline-block; position: relative;}
  .gu-editing-box::before { content: 'MODO LIBRE: ARRASTRA Y ESTIRA'; position: absolute; top: -20px; left: 0; font-family: var(--gu-font-tech); font-size: 8px; color: #00ffcc; letter-spacing: 2px; white-space: nowrap; }
  .gu-resize-handle { position: absolute; width: 10px; height: 10px; background: #00ffcc; border: 1px solid #000; display: none; z-index: 65; border-radius: 50%; }
  .gu-editing-box .gu-resize-handle { display: block; }
  .gu-resize-nw { top: -5px; left: -5px; cursor: nwse-resize; }
  .gu-resize-ne { top: -5px; right: -5px; cursor: nesw-resize; }
  .gu-resize-sw { bottom: -5px; left: -5px; cursor: nesw-resize; }
  .gu-resize-se { bottom: -5px; right: -5px; cursor: nwse-resize; }

  /* ================== MATERIALES 3D, METÁLICOS Y LUCES LED NEÓN ================== */
  .fx-none { text-shadow: 0 2px 15px rgba(0,0,0,0.9); background: none; -webkit-text-fill-color: initial; }
  .fx-custom-shadow { text-shadow: 1px 1px 0 var(--gu-shadow-color, #000), 2px 2px 0 var(--gu-shadow-color, #000), 3px 3px 0 var(--gu-shadow-color, #000), 4px 4px 10px rgba(0,0,0,0.8) !important; background: none; -webkit-text-fill-color: initial; }
  .fx-3d-pro { text-shadow: 1px 1px 0 #444, 2px 2px 0 #444, 3px 3px 0 #333, 4px 4px 0 #333, 5px 5px 0 #222, 6px 6px 0 #222, 7px 7px 10px rgba(0,0,0,0.8) !important; background: none; -webkit-text-fill-color: initial; }

