  /* Especiales (Simpson, Dragón Ball, Blood) */
  .fx-simpson { text-shadow: 2px 2px 0 #000, -2px -2px 0 #000, 2px -2px 0 #000, -2px 2px 0 #000, 4px 4px 0 rgba(0,0,0,0.5) !important; color: #FFD90F !important; font-family: 'Luckiest Guy', cursive !important; background: none; -webkit-text-fill-color: initial; }
  .fx-dragonball { text-shadow: 2px 2px 0 #ff0000, -2px -2px 0 #ff0000, 2px -2px 0 #ff0000, -2px 2px 0 #ff0000, 4px 4px 0 #000 !important; color: #ffcc00 !important; font-family: 'Bangers', cursive !important; background: none; -webkit-text-fill-color: initial; }
  .fx-blood { text-shadow: 2px 2px 0 #330000, 0 5px 5px rgba(255,0,0,0.5) !important; color: #cc0000 !important; font-family: 'Nosifer', cursive !important; background: none; -webkit-text-fill-color: initial; }







  /* ==========================================================================
     V24.1 MAIN PLAYER — UN SOLO BOTÓN MAESTRO
     Solo reproductor principal. No afecta emuladores ni módulos del creador.
     ========================================================================== */
  #gravity-ultra-wrapper .gu-main-secondary-toggle{
    display:none !important;
  }

  #gravity-ultra-wrapper .gu-main-master-toggle{
    width:30px;
    height:56px;
    left:-30px;
    border-radius:9px 0 0 9px;
    background:rgba(8,10,14,.72);
    border-color:rgba(255,255,255,.14);
    box-shadow:-5px 0 18px rgba(0,0,0,.38),0 0 12px rgba(255,0,51,.08);
    z-index:90;
  }

  #gravity-ultra-wrapper .gu-main-master-toggle:hover{
    background:color-mix(in srgb,var(--gu-neon) 13%,rgba(8,10,14,.78));
    border-color:var(--gu-neon);
    box-shadow:-5px 0 20px rgba(0,0,0,.48),0 0 14px var(--gu-neon);
  }

  #gravity-ultra-wrapper #gu-main-panel-glass.hidden-panel .gu-main-master-toggle{
    left:-48px !important;
    top:50% !important;
    opacity:1 !important;
    pointer-events:auto !important;
  }

  #gravity-ultra-wrapper #gu-main-panel-glass.hidden-panel .gu-main-master-toggle svg{
    transform:scaleX(-1);
  }

  #gravity-ultra-wrapper #gu-main-panel-glass,
  #gravity-ultra-wrapper #gu-main-glass-tubes{
    transition:transform .38s cubic-bezier(.25,.46,.45,.94),opacity .30s ease !important;
  }

  /* ==========================================================================
     V18.2 PC RIGHT DOCK - UN SOLO BOTÓN MAESTRO
     Unifica panel de opciones + slider + cristales/filtros sin tocar su lógica.
     ========================================================================== */
  #gu-live-preview-wrapper .gu-live-secondary-toggle {
    display: none !important;
  }

  #gu-live-preview-wrapper .gu-live-master-toggle {
    width: 30px;
    height: 56px;
    left: -30px;
    border-radius: 9px 0 0 9px;
    background: rgba(8,10,14,.72);
    border-color: rgba(255,255,255,.14);
    box-shadow: -5px 0 18px rgba(0,0,0,.38), 0 0 12px rgba(255,0,51,.08);
    z-index: 90;
  }
  #gu-live-preview-wrapper .gu-live-master-toggle:hover {
    background: rgba(255,0,51,.13);
    border-color: var(--gu-neon);
    box-shadow: -5px 0 20px rgba(0,0,0,.48), 0 0 14px var(--gu-neon);
  }

  /* Cuando se cierra el dock completo, el único botón permanece accesible. */
  #gu-live-preview-wrapper #gu-live-panel-glass.hidden-panel .gu-live-master-toggle {
    left: -48px !important;
    top: 50% !important;
    opacity: 1 !important;
    pointer-events: auto !important;
  }
  #gu-live-preview-wrapper #gu-live-panel-glass.hidden-panel .gu-live-master-toggle svg {
    transform: scaleX(-1);
  }

  /* Ambos bloques se retraen de manera sincronizada; el reproductor no cambia. */
  #gu-live-preview-wrapper #gu-live-panel-glass,
  #gu-live-preview-wrapper #gu-live-glass-tubes {
    transition: transform .38s cubic-bezier(.25,.46,.45,.94), opacity .30s ease !important;
  }


  /* AJUSTE FINO V17.1 - ALINEACIÓN DE FLECHAS LATERALES */
  #gu-live-preview-wrapper .gu-panel-glass.hidden-panel .gu-panel-toggle {
    left: -46px;
    top: 45%;
  }
  #gu-live-preview-wrapper .gu-glass-tubes.hidden-tubes .gu-tubes-toggle {
    right: auto;
    left: -46px;
    top: 34%;
  }
  #gu-live-preview-wrapper .gu-panel-toggle,
  #gu-live-preview-wrapper .gu-tubes-toggle {
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 0 10px rgba(0,0,0,0.55);
  }
  #gu-live-preview-wrapper #gu-live-panel-glass.hidden-panel .gu-live-master-toggle {
    left: -48px !important;
    top: 50% !important;
  }




  /* ==========================================================================
     V18.3 ONE BUTTON - SMART TV + MÓVIL
     Replica la solución aprobada en PC: un solo botón controla panel + barras.
     ========================================================================== */

  /* SMART TV: ocultar el segundo botón y usar el botón del panel como maestro. */
  #gu-tv-preview-wrapper .gu-tv-secondary-toggle {
    display: none !important;
  }
  #gu-tv-preview-wrapper .gu-tv-master-toggle {
    width: 30px;
    height: 56px;
    left: -30px;
    border-radius: 9px 0 0 9px;
    background: rgba(8,10,14,.72);
    border-color: rgba(255,255,255,.14);
    box-shadow: -5px 0 18px rgba(0,0,0,.38), 0 0 12px rgba(255,0,51,.08);
    z-index: 90;
  }
  #gu-tv-preview-wrapper .gu-tv-master-toggle:hover {
    background: rgba(255,0,51,.13);
    border-color: var(--gu-neon);
    box-shadow: -5px 0 20px rgba(0,0,0,.48), 0 0 14px var(--gu-neon);
  }
  #gu-tv-preview-wrapper #gu-tv-panel-glass.hidden-panel .gu-tv-master-toggle {
    left: -48px !important;
    top: 50% !important;
    opacity: 1 !important;
    pointer-events: auto !important;
  }
  #gu-tv-preview-wrapper #gu-tv-panel-glass.hidden-panel .gu-tv-master-toggle svg {
    transform: scaleX(-1);
  }
  #gu-tv-preview-wrapper #gu-tv-panel-glass,
  #gu-tv-preview-wrapper #gu-tv-glass-tubes {
    transition: transform .38s cubic-bezier(.25,.46,.45,.94), opacity .30s ease !important;
  }

  /* MÓVIL: un solo botón externo controla panel y filtros verticales. */
  #gu-mobile-workbench-v18 .gu-mobile-secondary-toggle-v18 {
    display: none !important;
  }
  #gu-mobile-workbench-v18 #gu-mob-master-toggle-external {
    width: 30px;
    height: 56px;
    border-color: rgba(255,255,255,.15);
    background: rgba(8,10,14,.72);
    box-shadow: 0 6px 18px rgba(0,0,0,.45), 0 0 12px rgba(255,0,51,.08);
  }
  #gu-mobile-workbench-v18 #gu-mob-master-toggle-external:hover {
    border-color: var(--gu-neon);
    background: rgba(255,0,51,.12);
    box-shadow: 0 0 16px color-mix(in srgb, var(--gu-neon) 42%, transparent);
  }
  #gu-mobile-workbench-v18 #gu-mob-master-toggle-external[aria-expanded='false'] {
    color: var(--gu-neon);
    border-color: var(--gu-neon);
  }

