  /* ========================================================================== 
     GRAVITY ULTRA V20 - TYPO LOGO STUDIO PRO (ADITIVO / NO DESTRUCTIVO)
     ========================================================================== */
  .gu-logo-studio { border-top:1px solid rgba(255,255,255,.10); margin-top:2px; padding-top:10px; }
  .gu-logo-studio-head { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:8px; }
  .gu-logo-studio-title { font-family:var(--gu-font-tech); font-size:9px; letter-spacing:2px; color:#00ffcc; font-weight:bold; }
  .gu-logo-pill { font-family:var(--gu-font-tech); font-size:7px; letter-spacing:1px; color:#00ffcc; border:1px solid rgba(0,255,204,.35); border-radius:10px; padding:3px 6px; background:rgba(0,255,204,.06); }
  .gu-logo-btn-row { display:grid; grid-template-columns:1fr 1fr; gap:6px; }
  .gu-logo-action { background:rgba(255,255,255,.035); border:1px solid rgba(255,255,255,.14); color:#fff; border-radius:5px; padding:7px 6px; cursor:pointer; font-family:var(--gu-font-tech); font-size:8px; letter-spacing:1px; transition:.2s; }
  .gu-logo-action:hover,.gu-logo-action.active { border-color:#00ffcc; color:#00ffcc; box-shadow:0 0 10px rgba(0,255,204,.18); }
  .gu-logo-field { margin-top:8px; }
  .gu-logo-field label { display:flex; justify-content:space-between; align-items:center; font-family:var(--gu-font-tech); color:var(--gu-muted); font-size:7.5px; letter-spacing:1px; margin-bottom:4px; }
  .gu-logo-field input[type='text'],.gu-logo-field select { width:100%; box-sizing:border-box; background:#050505; color:#fff; border:1px solid rgba(255,255,255,.17); border-radius:4px; padding:7px; font-family:var(--gu-font-tech); font-size:8px; outline:none; }
  .gu-logo-field input[type='text']:focus,.gu-logo-field select:focus { border-color:#00ffcc; }
  .gu-logo-colors { display:grid; grid-template-columns:repeat(6,1fr); gap:5px; margin-top:6px; }
  .gu-logo-color { -webkit-appearance:none; appearance:none; width:100%; height:26px; padding:0; border:1px solid rgba(255,255,255,.18); border-radius:5px; background:#000; overflow:hidden; cursor:pointer; }
  .gu-logo-color::-webkit-color-swatch-wrapper { padding:2px; }
  .gu-logo-color::-webkit-color-swatch { border:none; border-radius:3px; }
  .gu-logo-color::-moz-color-swatch { border:none; border-radius:3px; }
  .gu-logo-range { width:100%; accent-color:#00ffcc; cursor:pointer; }
  .gu-logo-range-row { display:grid; grid-template-columns:1fr 1fr; gap:7px; }
  .gu-typo-hint { margin-top:7px; padding:7px; border-radius:5px; border:1px solid rgba(255,255,255,.1); background:rgba(0,0,0,.45); color:var(--gu-muted); font-family:var(--gu-font-tech); font-size:7.5px; line-height:1.45; }
  .gu-typo-hint strong { color:#00ffcc; }
  .gu-typo-layer-list { display:grid; grid-template-columns:repeat(4,1fr); gap:5px; margin-top:7px; }
  .gu-typo-layer-btn { background:#050505; color:var(--gu-muted); border:1px solid rgba(255,255,255,.13); border-radius:4px; padding:6px 3px; cursor:pointer; font-family:var(--gu-font-tech); font-size:7px; letter-spacing:.8px; }
  .gu-typo-layer-btn.active { color:#001713; background:#00ffcc; border-color:#00ffcc; font-weight:bold; }
  .gu-typo-stage-chip { margin-top:6px; display:flex; gap:5px; flex-wrap:wrap; }
  .gu-typo-stage-chip span { border:1px solid rgba(0,255,204,.22); color:#91ffe9; border-radius:10px; padding:3px 6px; font:7px var(--gu-font-tech); letter-spacing:.7px; }
  #gu-live-typo-logo-stage { position:absolute; inset:0; z-index:44; pointer-events:none; }
  .gu-typo-logo-layer { position:absolute; left:18%; top:24%; min-width:80px; min-height:42px; display:none; align-items:center; justify-content:center; pointer-events:auto; cursor:move; transform-origin:center center; user-select:none; touch-action:none; white-space:nowrap; }
  .gu-typo-logo-layer.visible { display:flex; }
  .gu-typo-logo-text { display:inline-block; line-height:.92; font-weight:900; text-align:center; pointer-events:none; -webkit-background-clip:text; background-clip:text; }
  .gu-typo-logo-layer.active::after { content:'TYPO LAYER'; position:absolute; inset:-9px; border:1px dashed rgba(0,255,204,.68); border-radius:7px; pointer-events:none; color:#00ffcc; font:7px var(--gu-font-tech); letter-spacing:1px; padding:2px; box-sizing:border-box; }
  .gu-typo-resize-dot { position:absolute; right:-13px; bottom:-13px; width:10px; height:10px; border-radius:50%; background:#00ffcc; border:1px solid #001b16; box-shadow:0 0 8px rgba(0,255,204,.8); display:none; cursor:nwse-resize; pointer-events:auto; }
  .gu-typo-logo-layer.active .gu-typo-resize-dot { display:block; }
  @media(max-width:768px){ .gu-typo-logo-layer{ transform-origin:center center; } }

  /* ==========================================================================
     GRAVITY ULTRA V17 SAFE - CAPA DE MEJORA NO DESTRUCTIVA
     Mantiene intacto el núcleo V16 y mejora UX, responsive y accesibilidad.
     ========================================================================== */
  :root {
    --gu-v17-panel: rgba(8, 10, 14, 0.78);
    --gu-v17-border: rgba(255,255,255,0.11);
    --gu-v17-soft: rgba(255,255,255,0.06);
    --gu-v17-ok: #00ffcc;
  }

  #gu-creator-zone { overflow: hidden; isolation: isolate; }
  #gu-creator-zone::before {
    content: ""; position:absolute; inset:0; pointer-events:none; z-index:1;
    background:
      linear-gradient(90deg, transparent 0 49.8%, rgba(255,255,255,.018) 50%, transparent 50.2%),
      linear-gradient(0deg, transparent 0 49.8%, rgba(255,255,255,.012) 50%, transparent 50.2%);
    background-size: 52px 52px;
    mask-image: linear-gradient(to bottom, rgba(0,0,0,.45), transparent 78%);
  }

  .gu-cz-content { max-width: 100%; box-sizing: border-box; }
  .gu-cz-grid { align-items: start; }
  .gu-cz-col {
    min-width: 0; padding: 18px; border-radius: 12px;
    background: linear-gradient(180deg, rgba(255,255,255,.035), rgba(255,255,255,.012));
    border: 1px solid var(--gu-v17-border);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.035);
  }

  .gu-cz-title {
    display:flex; align-items:center; gap:10px; min-height:28px;
    text-shadow: 0 0 18px rgba(255,0,51,.22);
  }
  .gu-cz-title::before { content:"V17"; font:700 8px/1 var(--gu-font-tech); color:#000; background:var(--gu-v17-ok); padding:5px 7px; border-radius:4px; letter-spacing:1px; box-shadow:0 0 14px rgba(0,255,204,.3); }

  .gu-cz-input, .gu-cz-select, .gu-cz-code-box {
    transition: border-color .2s ease, box-shadow .2s ease, background-color .2s ease, transform .2s ease;
  }
  .gu-cz-input:hover, .gu-cz-select:hover { border-color: rgba(255,255,255,.28); }
  .gu-cz-input:focus, .gu-cz-select:focus, .gu-cz-code-box:focus {
    outline: none; border-color: var(--gu-neon); box-shadow: 0 0 0 2px color-mix(in srgb, var(--gu-neon) 18%, transparent), 0 0 18px color-mix(in srgb, var(--gu-neon) 18%, transparent);
  }

  .gu-cz-btn-gen, .gu-cz-btn-add, .gu-v17-action {
    position:relative; overflow:hidden; transform:translateZ(0);
  }
  .gu-cz-btn-gen:active, .gu-cz-btn-add:active, .gu-v17-action:active { transform: translateY(1px) scale(.995); }

  .gu-v17-toolbar {
    display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin-top:-8px; margin-bottom:4px;
  }
  .gu-v17-action {
    appearance:none; border:1px solid var(--gu-v17-border); color:#fff; background:rgba(0,0,0,.38);
    border-radius:6px; padding:9px 12px; cursor:pointer; font:700 9px/1 var(--gu-font-tech); letter-spacing:1px;
    transition:.2s ease; text-transform:uppercase;
  }
  .gu-v17-action:hover { border-color:var(--gu-neon); color:var(--gu-neon); box-shadow:0 0 14px color-mix(in srgb, var(--gu-neon) 28%, transparent); }
  .gu-v17-action.gu-v17-primary { color:#00130f; background:var(--gu-v17-ok); border-color:var(--gu-v17-ok); }
  .gu-v17-action.gu-v17-primary:hover { color:#00130f; filter:brightness(1.08); }
  .gu-v17-action.gu-v17-danger:hover { color:#ff5b71; border-color:#ff5b71; box-shadow:0 0 14px rgba(255,91,113,.25); }
  .gu-v17-status { margin-left:auto; color:var(--gu-muted); font:700 8px/1.2 var(--gu-font-tech); letter-spacing:1px; }
  .gu-v17-status.ok { color:var(--gu-v17-ok); }

  .gu-corel-panel { max-height: calc(100% - 110px); overflow:auto; scrollbar-width:thin; scrollbar-color:var(--gu-neon) transparent; }
  .gu-corel-panel::-webkit-scrollbar { width:5px; }
  .gu-corel-panel::-webkit-scrollbar-thumb { background:var(--gu-neon); border-radius:10px; }

  .gu-ghost-edit-btn:focus-visible, .gu-panel-toggle:focus-visible, .gu-tubes-toggle:focus-visible,
  .gu-font-arrow:focus-visible, .gu-fs-btn:focus-visible, .gu-vol-btn:focus-visible,
  .gu-cz-btn-gen:focus-visible, .gu-cz-btn-add:focus-visible, .gu-v17-action:focus-visible {
    outline:2px solid #fff; outline-offset:3px;
  }

  .gu-video-wrapper { contain: layout paint; }
  .gu-main-video { backface-visibility:hidden; }
  .gu-panel-glass, .gu-glass-tubes, .gu-corel-panel { will-change: transform, opacity; }

  @media (max-width: 900px) {
    .gu-cz-content { padding:22px; }
    .gu-cz-grid { grid-template-columns:1fr; gap:16px; }
    .gu-cz-col { padding:14px; }
    .gu-v17-status { width:100%; margin-left:0; margin-top:4px; }
    .gu-poster-horizontal { max-width:100% !important; height:auto !important; aspect-ratio:16/9; }
  }

  @media (max-width: 768px) {
    #gu-creator-zone { width:100%; margin-top:16px; border-radius:0; }
    .gu-cz-content { padding:16px 12px 28px; }
    .gu-cz-title { font-size:11px; letter-spacing:2px; }
    .gu-cz-label { letter-spacing:1.2px; line-height:1.35; }
    .gu-cz-input, .gu-cz-select { min-height:44px; font-size:12px; }
    .gu-cz-code-box { height:150px; font-size:10px; }
    .gu-v17-action { min-height:40px; }
    #gu-live-preview-wrapper:not(.gu-emul-mobile):not(.gu-emul-tv) .gu-corel-panel {
      top:52px; right:10px; width:min(220px, calc(100% - 20px)); max-height:calc(100% - 64px);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation-duration:.001ms !important; animation-iteration-count:1 !important; transition-duration:.001ms !important; scroll-behavior:auto !important; }

    /* V22.1: indicador NEURAL LINK solicitado como señal viva permanente */
    .gu-pulse-dot {
      animation-name: gu-pulse !important;
      animation-duration: 1.25s !important;
      animation-timing-function: ease-in-out !important;
      animation-iteration-count: infinite !important;
      animation-play-state: running !important;
    }
  }



  /* ==========================================================================\n     GRAVITY ULTRA V18.1 - MOBILE WORKBENCH PRO\n     Herramientas externas independientes + retraído suave, estable y no destructivo.\n     ========================================================================== */
  #gu-mobile-workbench-v18 {
    width: 100%;
    box-sizing: border-box;
    display: grid;
    grid-template-columns: 180px minmax(380px, 500px) 330px;
    gap: 18px;
    align-items: center;
    justify-content: center;
    min-height: 360px;
    padding: 18px 12px 28px;
    overflow: visible;
    position: relative;
