  /* ======================================================================
     V23 AUDIO BANKS PRO — SOLO PANEL DE ENLACES / SIN ALTERAR REPRODUCTORES
     ====================================================================== */
  .gu-audio-bank-head{
    display:flex; align-items:center; justify-content:space-between; gap:12px;
    margin:0 0 10px 0; min-height:38px;
  }
  .gu-audio-bank-state{
    display:flex; align-items:center; gap:9px; min-width:0;
    color:rgba(255,255,255,.78); font-size:9px; font-weight:800;
    letter-spacing:2.2px; text-transform:uppercase;
  }
  .gu-audio-bank-state::before{
    content:""; width:6px; height:6px; flex:0 0 6px; border-radius:50%;
    background:var(--gu-neon); box-shadow:0 0 12px var(--gu-neon);
  }
  #gu-audio-bank-name{color:#fff;text-shadow:0 0 8px rgba(255,255,255,.18)}
  .gu-audio-switch{
    width:38px; height:32px; flex:0 0 38px; border-radius:8px;
    border:1px solid color-mix(in srgb, var(--gu-neon) 58%, rgba(255,255,255,.18));
    background:
      linear-gradient(180deg,rgba(234,247,255,.055),rgba(255,255,255,.012)),
      color-mix(in srgb, var(--gu-neon) 7%, rgba(7,10,14,.94));
    color:#EAF7FF;
    cursor:pointer; display:flex; align-items:center; justify-content:center;
    box-shadow:
      inset 0 0 0 1px rgba(255,255,255,.025),
      inset 0 0 14px color-mix(in srgb, var(--gu-neon) 10%, transparent),
      0 0 10px color-mix(in srgb, var(--gu-neon) 18%, transparent),
      0 7px 22px rgba(0,0,0,.20);
    transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease,background .18s ease;
  }
  .gu-audio-switch:hover{
    border-color:var(--gu-neon);
    background:
      linear-gradient(180deg,rgba(234,247,255,.075),rgba(255,255,255,.018)),
      color-mix(in srgb, var(--gu-neon) 11%, rgba(7,10,14,.94));
    box-shadow:
      inset 0 0 0 1px rgba(255,255,255,.04),
      inset 0 0 16px color-mix(in srgb, var(--gu-neon) 14%, transparent),
      0 0 16px color-mix(in srgb, var(--gu-neon) 32%, transparent),
      0 7px 22px rgba(0,0,0,.20);
  }
  .gu-audio-switch:active{transform:scale(.96)}
  .gu-audio-switch svg{
    width:18px;height:18px;display:block;
    color:#EAF7FF;
    filter:drop-shadow(0 0 3px rgba(234,247,255,.32));
  }

  .gu-audio-bank{
    display:none;
    transform-origin:left center;
  }
  .gu-audio-bank.active{
    display:block;
    animation:guAudioBankIn .34s cubic-bezier(.2,.72,.25,1) both;
  }
  @keyframes guAudioBankIn{
    from{opacity:0;transform:translateX(-24px);filter:blur(2px)}
    to{opacity:1;transform:translateX(0);filter:blur(0)}
  }
  .gu-audio-bank .gu-cz-input{width:100%;box-sizing:border-box}
  .gu-audio-bank-note{
    display:block; margin:-2px 0 10px 0;
    color:rgba(255,255,255,.34); font-size:8px; letter-spacing:1.35px;
    text-transform:uppercase;
  }


  /* ==========================================================================
     V25 DEVICE EXPERIENCE ENGINE
     MÓVIL TÁCTIL + SMART TV REMOTE. Capa aislada y no destructiva.
     ========================================================================== */

  /* Móvil real y emulador móvil: objetivos táctiles cómodos y respuesta directa. */
  .gu-device-mobile-mode .gu-btn-play,
  .gu-device-mobile-mode .gu-fs-btn,
  .gu-device-mobile-mode .gu-vol-btn,
  .gu-device-mobile-mode .gu-panel-toggle,
  .gu-device-mobile-mode .gu-carousel-arrow,
  .gu-device-mobile-mode .gu-drop-opt,
  .gu-device-mobile-mode .gu-option-row {
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }

  .gu-device-mobile-mode .gu-fs-btn,
  .gu-device-mobile-mode .gu-vol-btn {
    min-width: 44px;
    min-height: 44px;
  }

  .gu-device-mobile-mode .gu-progress-container {
    min-height: 28px;
    touch-action: none;
  }

  .gu-device-mobile-mode .gu-progress-container::before {
    content:"";
    position:absolute;
    left:0;
    right:0;
    top:-10px;
    bottom:-10px;
  }

  /* Fullscreen móvil: el reproductor llena el viewport sin deformarse. */
  .gu-device-mobile-mode:fullscreen,
  .gu-device-mobile-mode.gu-mobile-fullscreen,
  .gu-device-mobile-mode:-webkit-full-screen {
    width:100vw !important;
    height:100vh !important;
    max-width:none !important;
    max-height:none !important;
    margin:0 !important;
    border-radius:0 !important;
    background:#000 !important;
  }

  .gu-device-mobile-mode:fullscreen .gu-video-wrapper,
  .gu-device-mobile-mode.gu-mobile-fullscreen .gu-video-wrapper,
  .gu-device-mobile-mode:-webkit-full-screen .gu-video-wrapper {
    width:100% !important;
    height:100% !important;
    min-height:100% !important;
    border-radius:0 !important;
  }

  .gu-device-mobile-mode:fullscreen .gu-main-video,
  .gu-device-mobile-mode.gu-mobile-fullscreen .gu-main-video,
  .gu-device-mobile-mode:-webkit-full-screen .gu-main-video {
    width:100% !important;
    height:100% !important;
    object-fit:contain !important;
    background:#000 !important;
  }

  /* Smart TV: foco visible estilo app de televisión, sin modificar estética base. */
  .gu-device-tv-mode [data-gu-tv-focusable="true"] {
    outline:none;
  }

  .gu-device-tv-mode [data-gu-tv-focusable="true"]:focus {
    position:relative;
    z-index:120 !important;
    outline:2px solid #EAF7FF !important;
    outline-offset:4px !important;
    border-color:var(--gu-neon) !important;
    box-shadow:
      0 0 0 2px rgba(0,0,0,.62),
      0 0 16px color-mix(in srgb,var(--gu-neon) 55%,transparent) !important;
  }

  .gu-device-tv-mode .gu-progress-container:focus {
    outline:2px solid #EAF7FF !important;
    outline-offset:6px !important;
  }

  .gu-device-tv-mode .gu-ui-layer {
    transition:opacity .22s ease !important;
  }

  .gu-device-tv-mode .gu-btn-play {
    cursor:default;
  }

  /* En TV no dependemos del hover. El foco del mando es la señal principal. */
  @media (hover:none) and (pointer:coarse) {
    .gu-device-mobile-mode .gu-panel-toggle:hover,
    .gu-device-mobile-mode .gu-carousel-arrow:hover,
    .gu-device-mobile-mode .gu-fs-btn:hover,
    .gu-device-mobile-mode .gu-vol-btn:hover {
      transform:none;
    }
  }


  /* ==========================================================================
     V26 GRAVITY SHIELD CORE — CLIENT DEFENSE PHASE 1
     Solo protege el reproductor publicado/iframe. El editor permanece libre.
     ========================================================================== */
  #gu-shield-badge{
    position:absolute;left:18px;bottom:18px;z-index:180;display:none;
    align-items:center;gap:8px;padding:7px 10px;border-radius:999px;
    border:1px solid rgba(234,247,255,.14);background:rgba(5,8,12,.58);
    color:#EAF7FF;font:700 8px/1 var(--gu-font-tech);letter-spacing:1.45px;
    text-transform:uppercase;pointer-events:none;backdrop-filter:blur(10px);
