  .gu-shield-card{
    width:min(520px,94vw);border:1px solid rgba(255,255,255,.12);border-radius:18px;
    padding:28px 26px;background:linear-gradient(145deg,rgba(255,255,255,.035),rgba(0,0,0,.25));
    box-shadow:0 24px 80px rgba(0,0,0,.55),0 0 34px rgba(255,0,51,.10);
