  #gu-tv-preview-wrapper #gu-tv-category-tabs.gu-device-top-tabs .gu-ghost-edit-btn {
    margin-left:0 !important;
  }

  .gu-device-design-panel { width:220px !important; }
  .gu-device-design-panel .gu-device-note {
    color:#8affea; font:7.5px var(--gu-font-tech); letter-spacing:.8px;
