    border-radius:5px; background:rgba(0,0,0,.35);
  }
  #gu-mob-preview-wrapper .gu-device-design-panel {
    top:43px !important;
    right:8px !important;
    width:205px !important;
    max-height:calc(100% - 52px) !important;
    padding:9px !important;
    gap:7px !important;
  }
  #gu-mob-preview-wrapper .gu-device-design-panel .gu-corel-title { font-size:10px; }
  #gu-mob-preview-wrapper .gu-device-design-panel .gu-corel-label { font-size:7px; }
  #gu-mob-preview-wrapper .gu-device-design-panel .gu-corel-select { font-size:7px; }
  #gu-tv-preview-wrapper .gu-device-design-panel {
