  #gu-mob-title-box, #gu-tv-title-box { display:inline-block; position:relative; }
  #gu-mob-title-box.gu-editing-box::before { font-size:5.5px; top:-14px; letter-spacing:1px; }
  #gu-mob-title-box .gu-resize-handle { width:7px; height:7px; }

  @media(max-width:900px){
    #gu-mobile-workbench-v18 .gu-mobile-left-tools-v18 #gu-mob-category-tabs.gu-device-side-tabs {
      width:136px !important;
    }
