    }
  }



/* VISTA ÚNICA: sólo el reproductor estándar PC; sin editor creador ni otros emuladores */
html{min-height:100%;background:#050505}body{background:#050505!important;min-height:100vh;display:flex!important;justify-content:flex-start;align-items:center;flex-direction:column;margin:0!important;padding:clamp(24px,7vh,85px) 0 30px!important;overflow-x:hidden}
body:before{display:none!important}
#gu-live-preview-wrapper{width:calc(100vw - 48px);max-width:1400px;margin:0 auto!important;aspect-ratio:21/9!important;border-radius:12px;box-shadow:0 18px 58px rgba(0,0,0,.9),0 0 33px var(--gu-neon);flex-shrink:0;isolation:isolate}
#gu-live-preview-wrapper .gu-category-tabs{display:flex!important;opacity:1;pointer-events:auto}
#gu-live-preview-wrapper .gu-font-nav{opacity:1;pointer-events:auto}
#gu-live-preview-wrapper:hover .gu-font-nav{opacity:1;pointer-events:auto}
#gu-live-preview-wrapper .gu-panel-glass,#gu-live-preview-wrapper .gu-glass-tubes{max-height:90%}
#gu-live-preview-wrapper .gu-corel-panel{max-height:calc(100% - 85px);overflow-y:auto;scrollbar-width:thin}
#gu-live-preview-wrapper .gu-panel-glass.hidden-panel{transform:translate3d(calc(100% + 65px),-50%,0)!important}
#gu-live-preview-wrapper .gu-glass-tubes.hidden-tubes{transform:translate3d(calc(100% + 15px),-50%,0)!important}
#gu-live-preview-wrapper .gu-ui-container{pointer-events:none}
#gu-live-preview-wrapper .gu-corel-panel.visible{pointer-events:auto}
#gu-live-preview-wrapper .gu-typo-logo-layer.visible{pointer-events:auto}
#gu-local-video-file{display:none}
@media(max-width:900px){body{padding-top:10px!important}#gu-live-preview-wrapper{width:100%;aspect-ratio:16/9!important;border-radius:0}#gu-live-preview-wrapper .gu-category-tabs{top:8px;gap:4px}#gu-live-preview-wrapper .gu-cat-btn{font-size:7px;padding:6px 8px}#gu-live-preview-wrapper .gu-ghost-edit-btn{font-size:7px;padding:6px;margin-left:0}#gu-live-preview-wrapper .gu-panel-glass{right:35px;width:180px;padding:10px}#gu-live-preview-wrapper .gu-glass-tubes{right:6px;gap:4px}#gu-live-preview-wrapper .gu-movie-info{left:26px;top:45%}#gu-live-preview-wrapper .gu-title{font-size:clamp(13px,2.5vw,24px)}#gu-live-preview-wrapper .gu-footer{bottom:9px;left:10px;right:10px}#gu-live-preview-wrapper .gu-corel-panel{right:15px;top:45px}}
@media(max-width:560px){#gu-live-preview-wrapper{min-height:310px;aspect-ratio:auto!important}#gu-live-preview-wrapper .gu-category-tabs{flex-wrap:wrap;width:95%;justify-content:center}#gu-live-preview-wrapper .gu-movie-info{top:39%;left:16px;max-width:48%}#gu-live-preview-wrapper .gu-top-left{top:60px;left:14px}#gu-live-preview-wrapper .gu-top-right{top:60px;right:12px}#gu-live-preview-wrapper .gu-panel-glass{right:27px;top:52%;width:146px;gap:8px}#gu-live-preview-wrapper .gu-glass-tubes{right:4px;top:52%}#gu-live-preview-wrapper .gu-tube{width:15px;height:140px}#gu-live-preview-wrapper .gu-footer{bottom:7px}#gu-live-preview-wrapper .gu-quality-label{font-size:8px}#gu-live-preview-wrapper .gu-corel-panel{width:200px;max-height:230px}}


/* GRAVITY ULTRA VIDEO STUDIO V2 — MÓDULO ADITIVO, NO DESTRUCTIVO */
.gu-ve-trigger{margin-left:9px!important;border:1px solid #f03563!important;color:#ff5c84!important;background:rgba(255,0,55,.07)!important;box-shadow:0 0 12px rgba(255,0,55,.18);font-family:var(--gu-font-tech);font-size:9px;letter-spacing:1.2px;border-radius:20px;padding:8px 13px;cursor:pointer;transition:.25s}
.gu-ve-trigger:hover{color:#fff!important;background:rgba(255,0,60,.24)!important;box-shadow:0 0 20px #ff003355}
#gu-ve-workspace{display:none;color:#f3f3f5;font-family:var(--gu-font-main);width:min(100%,1700px);margin:0 auto;min-height:100vh;background:radial-gradient(circle at top,#120308 0%,#070708 26%,#000 100%);border:1px solid rgba(255,255,255,.08);box-sizing:border-box;box-shadow:0 0 0 1px rgba(255,20,70,.12),0 0 35px rgba(255,0,51,.12),0 18px 80px #000}
body.gu-ve-active{padding:0!important;display:block!important;background:#141315!important;overflow-x:hidden}
body.gu-ve-active #gu-ve-workspace{display:flex;flex-direction:column;animation:guVeEnter .5s ease both}
@keyframes guVeEnter{from{opacity:0;transform:translateY(20px) scale(.985)}to{opacity:1;transform:none}}
#gu-ve-workspace *{box-sizing:border-box}
.gu-ve-header{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;border-bottom:1px solid rgba(255,255,255,.08);background:linear-gradient(180deg,rgba(10,10,12,.96),rgba(4,4,5,.95));backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);gap:12px;box-shadow:inset 0 -1px 0 rgba(255,255,255,.04)}
.gu-ve-brand{font:900 12px/1 var(--gu-font-tech);letter-spacing:3px;color:#fff;white-space:nowrap}.gu-ve-brand b{color:#ff315c}
.gu-ve-header-actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}
.gu-ve-btn{font:800 10px/1 var(--gu-font-tech);letter-spacing:1px;border:1px solid rgba(255,255,255,.14);color:#f6f3f5;background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,.03));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);padding:11px 14px;border-radius:12px;cursor:pointer;transition:.25s;white-space:nowrap;box-shadow:0 5px 18px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.06)}
.gu-ve-btn:hover{border-color:#ff315c;color:#fff;box-shadow:0 0 0 1px rgba(255,60,110,.28),0 0 22px rgba(255,0,70,.28),0 0 42px rgba(255,0,70,.15);transform:translateY(-1px)}.gu-ve-btn.primary{background:linear-gradient(180deg,#ff3260,#ea204f);border-color:#ff4b78;color:white;box-shadow:0 0 22px rgba(255,42,92,.25)}.gu-ve-btn.primary:hover{background:linear-gradient(180deg,#ff4e77,#f42b5d)}
.gu-ve-content{display:grid;grid-template-columns:174px minmax(0,1fr) 240px;gap:12px;padding:15px;min-height:400px;align-items:stretch}
.gu-ve-left{border-radius:16px;background:linear-gradient(180deg,rgba(12,12,14,.92),rgba(4,4,6,.9));border:1px solid rgba(255,255,255,.08);padding:12px 9px;display:flex;flex-direction:column;gap:11px;box-shadow:0 12px 34px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.04)}
.gu-ve-sidebtn{display:flex;align-items:center;gap:10px;width:100%;border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:12px 9px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.025));backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);color:#ddd;cursor:pointer;text-align:left;font:800 11px var(--gu-font-tech);letter-spacing:1.1px;transition:.28s;box-shadow:0 4px 15px rgba(0,0,0,.35)}
.gu-ve-sidebtn span{font-size:20px;color:#ff315c}.gu-ve-sidebtn:hover,.gu-ve-sidebtn.active{border-color:#ff315c;background:linear-gradient(180deg,rgba(255,70,120,.16),rgba(255,20,70,.08));color:#fff;box-shadow:0 0 0 1px rgba(255,70,120,.14),0 0 20px rgba(255,20,70,.18)}
.gu-ve-sidebar-note{font:9px/1.6 var(--gu-font-tech);color:#8d868f;padding:8px;letter-spacing:.3px}
.gu-ve-stage{display:flex;flex-direction:column;min-width:0;gap:10px;justify-content:center;position:relative}
.gu-ve-stage-header{font:800 9px var(--gu-font-tech);letter-spacing:2px;color:#a5a0a7;display:flex;justify-content:space-between}
#gu-ve-player-slot{display:flex;align-items:center;justify-content:center;min-width:0;flex:1;min-height:290px;position:relative}
body.gu-ve-active #gu-live-preview-wrapper{width:100%!important;max-width:100%!important;margin:0!important;aspect-ratio:16/9!important;min-height:0!important;box-shadow:0 0 0 1px rgba(255,50,100,.24),0 0 36px rgba(255,0,64,.22),0 0 85px rgba(255,0,43,.16)!important;border-radius:16px!important;transform:none!important;overflow:hidden}
body.gu-ve-active #gu-live-preview-wrapper .gu-category-tabs,body.gu-ve-active #gu-live-preview-wrapper .gu-font-nav,body.gu-ve-active #gu-live-preview-wrapper .gu-movie-info,body.gu-ve-active #gu-live-preview-wrapper .gu-panel-glass,body.gu-ve-active #gu-live-preview-wrapper .gu-glass-tubes,body.gu-ve-active #gu-live-preview-wrapper .gu-corel-panel,body.gu-ve-active #gu-live-preview-wrapper #gu-live-typo-logo-stage,body.gu-ve-active #gu-live-preview-wrapper .gu-cinematic-tint{display:none!important}
body.gu-ve-active #gu-live-preview-wrapper .gu-core{transform:translate(-50%,-50%) scale(.78)}
body.gu-ve-active #gu-live-preview-wrapper .gu-top-left{top:15px;left:19px}body.gu-ve-active #gu-live-preview-wrapper .gu-top-right{top:15px;right:19px}
body.gu-ve-active #gu-live-preview-wrapper .gu-footer{bottom:16px;left:19px;right:19px}
body.gu-ve-active #gu-live-preview-wrapper .gu-ui-hidden .gu-top-left,body.gu-ve-active #gu-live-preview-wrapper .gu-ui-hidden .gu-top-right,body.gu-ve-active #gu-live-preview-wrapper .gu-ui-hidden .gu-footer{opacity:1!important;transform:none!important}
body.gu-ve-active #gu-live-preview-wrapper.gu-cursor-hidden,body.gu-ve-active #gu-live-preview-wrapper.gu-cursor-hidden *{cursor:auto!important}
#gu-ve-grade-preview{display:none;position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2;pointer-events:none}
body.gu-ve-active #gu-ve-grade-preview{display:block}
body.gu-ve-active #gu-live-video{opacity:0!important}
.gu-ve-right{background:linear-gradient(180deg,rgba(11,11,13,.94),rgba(3,3,5,.92));border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:12px 12px 10px;display:flex;flex-direction:column;gap:8px;align-items:center;box-shadow:0 12px 34px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.04)}
.gu-ve-panel-title{font:800 10px var(--gu-font-tech);letter-spacing:1.4px;text-align:center;color:#eee}
.gu-ve-wheel-grid{display:flex;flex-direction:column;align-items:center;gap:8px;width:100%}
.gu-ve-wheel-wrap{display:flex;align-items:center;gap:10px;width:100%;justify-content:center}
.gu-ve-wheel{position:relative;width:103px;height:103px;flex:0 0 103px;border-radius:50%;cursor:crosshair;touch-action:none;border:4px solid #333;box-shadow:0 2px 12px #000,inset 0 0 0 4px #171717;background:conic-gradient(red,#ff0,#0f0,#0ff,#00f,#f0f,red)}
.gu-ve-wheel:before{content:'';position:absolute;inset:6px;border-radius:50%;background:radial-gradient(circle at center,#999 0%,transparent 75%);pointer-events:none}
.gu-ve-wheel:after{content:'';position:absolute;inset:31%;border-radius:50%;background:#0d0b0d;border:3px solid #3e393d;box-shadow:0 0 6px #000;pointer-events:none}
.gu-ve-wheel-cursor{position:absolute;z-index:3;width:13px;height:13px;border-radius:50%;border:2px solid #fff;box-shadow:0 1px 4px #000;left:50%;top:50%;transform:translate(-50%,-50%);pointer-events:none}
.gu-ve-wheel-label{width:80px;font:800 8px/1.4 var(--gu-font-tech);letter-spacing:.8px;color:#bfb9c0;text-transform:uppercase;word-break:break-word}
.gu-ve-wheel-label b{display:block;font-size:11px;color:#fff;margin-top:3px}
.gu-ve-swatch-row{width:100%;display:grid;grid-template-columns:20px 1fr;gap:6px;align-items:center;font:800 10px var(--gu-font-tech);color:#ccc}
.gu-ve-swatch{height:24px;width:100%;border:2px solid #514d53;cursor:pointer;border-radius:3px}
.gu-ve-grade-note{font:9px/1.5 var(--gu-font-tech);color:#a19aa2;text-align:center}
.gu-ve-bottom{margin:0 15px 15px;padding:14px;background:linear-gradient(180deg,rgba(10,10,12,.94),rgba(4,4,6,.92));border:1px solid rgba(255,255,255,.08);border-radius:16px;display:grid;grid-template-columns:minmax(0,1fr) 55px;gap:10px;box-shadow:0 12px 34px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.04)}
.gu-ve-ruler-stack{min-width:0;display:flex;flex-direction:column;gap:8px;overflow:hidden}
.gu-ve-ruler{position:relative;height:91px;overflow:hidden;border:1px solid #5c595d;background:linear-gradient(90deg,#b2b0b3,#e2e0e1 40%,#b9b7ba);transition:transform .38s ease,opacity .38s ease,filter .38s ease;cursor:pointer}
.gu-ve-ruler:before,.gu-ve-ruler:after{content:'';position:absolute;left:0;right:0;height:21px;pointer-events:none;background:repeating-linear-gradient(90deg,#555 0px,#555 1px,transparent 1px,transparent 5px);mask-image:linear-gradient(to bottom,#000 0 65%,transparent);opacity:.65}
.gu-ve-ruler:before{top:0}.gu-ve-ruler:after{bottom:0;transform:rotate(180deg)}
.gu-ve-ruler-track{position:absolute;inset:25px 6px;display:flex;align-items:center;gap:3px;overflow:hidden}
.gu-ve-clip{display:flex;align-items:center;justify-content:center;min-width:50px;height:100%;padding:4px 10px;border:1px solid #9b8b95;border-radius:4px;background:#a8a4aa;color:#29252a;font:800 10px var(--gu-font-tech);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
.gu-ve-clip.selected{background:#f9cad5;border-color:#c62755;color:#691b34}
.gu-ve-ruler.ghost{opacity:.42;filter:grayscale(.4);transform:scaleY(.85)}
.gu-ve-playhead{position:absolute;top:0;bottom:0;left:0;width:2px;background:#ee2353;box-shadow:0 0 7px #ed2753;z-index:5;pointer-events:none}
.gu-ve-playhead:before{content:'';position:absolute;top:0;left:-5px;border-left:6px solid transparent;border-right:6px solid transparent;border-top:9px solid #ed2753}
.gu-ve-timeline-controls{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}
.gu-ve-swap{width:40px;height:40px;border:1px solid #d6547a;border-radius:10px;background:#34262f;color:#fff;font-size:20px;cursor:pointer;transition:.25s}
.gu-ve-swap:hover{background:#d32b57;transform:translateY(-2px)}
.gu-ve-time{font:700 10px var(--gu-font-tech);color:#fff;letter-spacing:1px}
.gu-ve-library{position:absolute;z-index:85;top:5px;left:6px;bottom:5px;width:min(390px,90%);display:none;flex-direction:column;background:rgba(23,21,26,.98);border:1px solid #66404e;border-radius:12px;box-shadow:0 12px 35px #000;padding:14px;animation:guVeEnter .2s ease}
.gu-ve-library.open{display:flex}.gu-ve-library-head{display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:12px}.gu-ve-library-title{font:800 11px var(--gu-font-tech);letter-spacing:1.6px}
.gu-ve-library-list{overflow:auto;flex:1;display:flex;flex-direction:column;gap:8px;min-height:70px}.gu-ve-item{display:flex;align-items:center;gap:9px;border:1px solid #403b42;background:#2a272d;border-radius:7px;padding:9px;color:#ddd;cursor:pointer;text-align:left;width:100%;font:10px/1.3 var(--gu-font-tech)}
.gu-ve-item:hover,.gu-ve-item.selected{border-color:#ff315c;background:#3c2a33}.gu-ve-item-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.gu-ve-item small{color:#ad9da8}
.gu-ve-add{margin-top:12px;display:block;text-align:center;border:1px dashed #ef2b57;color:#ff7694;padding:13px 8px;border-radius:8px;font:800 10px var(--gu-font-tech);cursor:pointer}
.gu-ve-add:hover{background:#3c2530}.gu-ve-file-input{display:none!important}
.gu-ve-status{font:9px/1.4 var(--gu-font-tech);color:#a9a2a9;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@media(max-width:1080px){.gu-ve-content{grid-template-columns:120px minmax(0,1fr) 180px;gap:8px;padding:9px}.gu-ve-wheel{width:86px;height:86px;flex-basis:86px}.gu-ve-wheel-label{width:54px;font-size:7px}.gu-ve-sidebtn{font-size:9px;padding:10px 5px}.gu-ve-header{padding:0 12px}}
@media(max-width:760px){.gu-ve-content{grid-template-columns:1fr;gap:8px}.gu-ve-left{flex-direction:row;flex-wrap:wrap;padding:8px}.gu-ve-sidebtn{width:auto;flex:1;justify-content:center}.gu-ve-sidebar-note{display:none}.gu-ve-right{gap:8px}.gu-ve-wheel-grid{flex-direction:row;flex-wrap:wrap;justify-content:space-around}.gu-ve-wheel-wrap{width:auto;flex-direction:column}.gu-ve-wheel-label{text-align:center;width:auto}.gu-ve-right .gu-ve-swatch-row{max-width:270px}.gu-ve-header{height:auto;min-height:55px;flex-wrap:wrap;padding:12px}.gu-ve-bottom{margin:0 8px 10px;padding:7px;grid-template-columns:minmax(0,1fr) 45px}.gu-ve-ruler{height:65px}#gu-ve-player-slot{min-height:170px}}
/* Vista final conserva la gradación y la imagen aplicada después de GUARDAR Y VOLVER */
body.gu-ve-graded:not(.gu-ve-active) #gu-ve-grade-preview{display:block}
body.gu-ve-graded:not(.gu-ve-active) #gu-live-video{opacity:0!important}

/* GRAVITY STUDIO V3 — ajustes aislados al editor */
#gu-live-title-box.gu-editing-box::before{display:none!important;content:none!important}
#gu-live-movie-info>.gu-status{display:none!important}
#gu-live-title-box.gu-editing-box,#gu-live-title-box.gu-editing-box .gu-title{touch-action:none;cursor:grab!important;user-select:none}
#gu-live-title-box.gu-editing-box .gu-title[contenteditable=true]{cursor:text!important;user-select:text}
body.gu-ve-active{height:100dvh!important;overflow:hidden!important}
body.gu-ve-active #gu-ve-workspace{width:100%!important;max-width:none;height:100dvh;min-height:0!important;overflow:hidden;display:grid!important;grid-template-rows:48px minmax(0,1fr) auto minmax(125px,24vh);animation:none}
#gu-ve-workspace .gu-ve-header{height:48px;padding:0 14px;min-height:0;flex-wrap:nowrap}
#gu-ve-workspace .gu-ve-content{min-height:0;padding:10px;grid-template-columns:142px minmax(0,1fr) 200px;gap:10px;overflow:hidden}
#gu-ve-workspace .gu-ve-left,#gu-ve-workspace .gu-ve-right,#gu-ve-workspace .gu-ve-stage{min-height:0;overflow:hidden}
#gu-ve-workspace .gu-ve-right{padding:8px;justify-content:center;gap:5px}
#gu-ve-workspace .gu-ve-wheel{width:clamp(42px,9vh,90px);height:clamp(42px,9vh,90px);flex-basis:clamp(42px,9vh,90px)}
#gu-ve-workspace .gu-ve-wheel-grid{gap:5px}
#gu-ve-workspace .gu-ve-grade-note{display:none}
#gu-ve-player-slot{min-height:0!important;overflow:hidden}
body.gu-ve-active #gu-live-preview-wrapper{height:100%!important;aspect-ratio:auto!important;min-height:0!important}
body.gu-ve-active #gu-live-preview-wrapper .gu-layer,#gu-ve-grade-preview{object-fit:contain!important}
body.gu-ve-active #gu-live-preview-wrapper .gu-gradient-shadow{display:none}
body.gu-ve-active #gu-live-preview-wrapper .gu-core{transform:translate(-50%,-50%) scale(.5)}
body.gu-ve-active #gu-live-preview-wrapper .gu-footer{left:12px;right:12px;bottom:10px;gap:10px}
body.gu-ve-active #gu-live-preview-wrapper .gu-t-tech{font-size:7px}
body.gu-ve-active #gu-live-preview-wrapper .gu-t-bold{font-size:8px}
#gu-ve-workspace .gu-ve-bottom{margin:0 10px 10px;padding:8px;min-height:0;overflow:hidden}
#gu-ve-workspace .gu-ve-ruler-stack{position:relative;gap:7px;overflow:hidden}
#gu-ve-workspace .gu-ve-ruler{height:calc((100% - 7px)/2);flex:0 0 calc((100% - 7px)/2);min-height:0;transform:none;transition:opacity .3s,filter .3s}
#gu-ve-workspace .gu-ve-ruler-track{inset:15px 4px 13px;gap:2px}
#gu-ve-workspace .gu-ve-ruler:before,#gu-ve-workspace .gu-ve-ruler:after{height:12px}
#gu-ve-workspace .gu-ve-ruler.ghost{opacity:.62;filter:saturate(.6)}
#gu-ve-workspace .gu-ve-clip{position:relative;border-radius:3px;padding:0;min-width:0;flex-shrink:0;background:#2c2830;height:100%;overflow:hidden}
.gu-v3-thumbs{position:absolute;inset:0;display:flex;pointer-events:none}.gu-v3-thumbs img{height:100%;min-width:0;flex:1;object-fit:cover}
.gu-v3-clip-label{position:absolute;bottom:0;left:0;right:0;padding:3px 5px;background:#000b;color:#fff;font:9px monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;pointer-events:none}
#gu-ve-workspace .gu-ve-clip.selected{outline:2px solid #ff315c;outline-offset:-2px;border-color:#ff315c}
#gu-ve-workspace .gu-ve-timeline-controls{gap:4px}
.gu-v3-arrow{width:34px;height:32px;display:grid;place-items:center;color:#ccc;border:1px solid #ffffff40;border-radius:9px;background:linear-gradient(130deg,#ffffff20,#ffffff04);backdrop-filter:blur(14px);cursor:pointer;transition:.2s}
.gu-v3-arrow:hover,.gu-v3-arrow:active,.gu-v3-arrow.lit{color:var(--gu-neon);border-color:var(--gu-neon);box-shadow:0 0 14px var(--gu-neon),inset 0 0 10px #ff315c22}
.gu-v3-arrow svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7}
.gu-v3-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:5px;padding:6px 10px;background:#1a191d;border-top:1px solid #39333c;border-bottom:1px solid #39333c;min-height:0}
.gu-v3-toolbar button,.gu-v3-tool,.gu-v3-toolbar select{border:1px solid #51414a;background:linear-gradient(#ffffff09,#ffffff02);color:#ddd;border-radius:6px;padding:7px 9px;font:10px var(--gu-font-main);cursor:pointer}
.gu-v3-toolbar button:hover,.gu-v3-tool:hover{border-color:#ff315c;color:#fff}.gu-v3-toolbar button:disabled{opacity:.3;cursor:default}.gu-v3-toolbar .on{color:#ff7796;border-color:#ff315c}
.gu-v3-secondary{display:none;min-height:0}.gu-v3-monitor{width:100%;height:100%;object-fit:contain;background:#080809;border:1px solid #453640;border-radius:5px}
.gu-v3-label{font:9px monospace;letter-spacing:1px;color:#b5a6b1;padding:5px 0}
body.gu-ve-active #gu-ve-workspace.gu-v3-expanded{grid-template-rows:48px minmax(0,1fr) auto minmax(170px,35vh)}
#gu-ve-workspace.gu-v3-expanded .gu-ve-content{grid-template-columns:minmax(160px,1fr) minmax(240px,1.4fr) minmax(160px,1fr)}
.gu-v3-expanded .gu-ve-left{gap:4px;padding:7px}.gu-v3-expanded .gu-ve-left>.gu-ve-sidebtn{display:none}.gu-v3-expanded .gu-ve-sidebar-note{display:none}
.gu-v3-expanded .gu-v3-secondary{display:flex;flex-direction:column;flex:1;min-height:0}
.gu-v3-expanded .gu-ve-right>*:not(.gu-v3-secondary){display:none!important}
.gu-v3-expanded .gu-ve-right>.gu-v3-secondary{width:100%;height:100%}
.gu-v3-monitor-box{flex:1;min-height:0;position:relative}
.gu-v3-trim{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:6px}
.gu-v3-trim label{font:9px monospace;color:#b6a6af}.gu-v3-trim input{width:100%;color:#eee;background:#18151b;border:1px solid #54414c;border-radius:4px;padding:4px;margin-top:3px}
.gu-v3-props{display:flex;flex-wrap:wrap;gap:5px;align-items:center;font:10px monospace}
.gu-v3-props select{max-width:100%;background:#231e26;color:#eee;border:1px solid #64515d;border-radius:4px;padding:4px}
.gu-v3-props input[type=range]{width:90px;accent-color:#ff315c}
.gu-v3-catalog{position:absolute;inset:0;z-index:95;background:#19171cf5;backdrop-filter:blur(18px);display:none;flex-direction:column;border:1px solid #624351;border-radius:8px;padding:10px}
.gu-v3-catalog.open{display:flex}.gu-v3-catalog-head{display:flex;gap:8px;align-items:center;font:11px monospace;margin-bottom:8px}.gu-v3-catalog-head input{flex:1;min-width:20px;padding:6px;background:#29222c;border:1px solid #655260;color:white;border-radius:5px}
.gu-v3-catalog-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:7px;min-height:0;flex:1}
.gu-v3-preset{min-width:0;min-height:0;border:1px solid #58424f;border-radius:6px;color:#ddd;background:#252027;padding:0;cursor:pointer;overflow:hidden;display:flex;flex-direction:column}.gu-v3-preset:hover,.gu-v3-preset.active{border-color:#ff315c;box-shadow:0 0 10px #ff315c44}.gu-v3-preset canvas{width:100%;height:100%;min-height:0;object-fit:cover;flex:1}.gu-v3-preset span{font:9px monospace;padding:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gu-v3-catalog-foot{display:flex;justify-content:space-between;align-items:center;gap:6px;padding-top:8px;font:10px monospace}
#gu-ve-workspace .gu-ve-library-list{scrollbar-width:none}#gu-ve-workspace .gu-ve-library-list::-webkit-scrollbar{display:none}
.gu-v3-hint{font:9px monospace;color:#bbadb6;margin-left:auto}
#gu-ve-workspace .gu-ve-stage-header{flex:0 0 auto;gap:8px}#gu-ve-active-file{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media(max-height:650px){#gu-ve-workspace .gu-ve-sidebar-note{display:none}#gu-ve-workspace .gu-ve-wheel{width:48px;height:48px;flex-basis:48px}#gu-ve-workspace .gu-ve-btn{padding:7px;font-size:9px}#gu-ve-workspace .gu-ve-header .gu-ve-status{display:none}#gu-ve-workspace .gu-ve-sidebtn{padding:8px}body.gu-ve-active #gu-ve-workspace.gu-v3-expanded{grid-template-rows:42px minmax(0,1fr) auto 28vh}#gu-ve-workspace .gu-ve-header{height:42px}}
@media(max-width:760px){#gu-ve-workspace .gu-ve-content{grid-template-columns:70px minmax(0,1fr) 105px;padding:5px;gap:5px}#gu-ve-workspace .gu-ve-left{flex-direction:column;flex-wrap:nowrap;padding:4px}#gu-ve-workspace .gu-ve-sidebtn{font-size:8px;gap:2px;padding:8px 2px;flex:0;justify-content:center;width:100%}#gu-ve-workspace .gu-ve-sidebtn span{display:none}#gu-ve-workspace .gu-ve-wheel-grid{flex-direction:column;flex-wrap:nowrap}#gu-ve-workspace .gu-ve-wheel-wrap{flex-direction:row}#gu-ve-workspace .gu-ve-wheel-label{display:none}#gu-ve-workspace .gu-ve-panel-title{font-size:8px}#gu-ve-workspace .gu-ve-header .gu-ve-brand{font-size:9px;letter-spacing:0}#gu-ve-workspace .gu-ve-header .gu-ve-status{display:none}#gu-ve-workspace .gu-ve-btn{font-size:8px;padding:7px}#gu-ve-workspace.gu-v3-expanded .gu-ve-content{grid-template-columns:minmax(75px,1fr) minmax(130px,1.5fr) minmax(75px,1fr)}.gu-v3-toolbar{gap:3px;padding:4px}.gu-v3-toolbar button{padding:5px;font-size:9px}.gu-v3-hint{display:none}.gu-v3-catalog-grid{grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(4,minmax(0,1fr))}.gu-v3-props{font-size:8px}.gu-v3-trim{gap:2px}.gu-v3-trim input{font-size:9px}.gu-v3-trim label{font-size:7px}}

/* ================================================================
   GRAVITY ULTRA V4 — MEJORAS AISLADAS; ESTÉTICA ORIGINAL PRESERVADA
   ================================================================ */
body.gu-ve-active #gu-ve-workspace{grid-template-rows:48px minmax(0,1fr) auto auto minmax(184px,32vh)!important}
#gu-ve-workspace .gu-ve-header-actions{display:flex;align-items:center;gap:7px;min-width:0}
.gu-v4-projectbar{display:flex;gap:5px;align-items:center}
#gu-ve-workspace .gu-ve-bottom{min-height:0;margin:0 10px 9px;padding:7px;grid-template-columns:minmax(0,1fr) 67px;gap:5px;overflow:hidden}
#gu-ve-workspace .gu-ve-ruler-stack{min-height:0;overflow:hidden;display:block;background:#1d1c21;border:1px solid #454047;border-radius:8px}
#gu-ve-workspace .gu-ve-timeline-controls{min-width:0;justify-content:start;gap:12px}
.gu-v4-trackbar{display:flex;gap:7px;align-items:center;flex-wrap:wrap;padding:6px 12px;color:#e6d5db;border-top:1px solid rgba(255,255,255,.06);background:linear-gradient(180deg,rgba(8,8,10,.98),rgba(2,2,3,.94));font:700 9px var(--gu-font-tech)}
.gu-v4-trackbar button{padding:5px 9px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02));color:#f3e7eb;font:700 9px var(--gu-font-tech);cursor:pointer;box-shadow:0 4px 12px rgba(0,0,0,.28)}
.gu-v4-trackbar button:hover{color:#fff;border-color:#ff315c;box-shadow:0 0 0 1px rgba(255,60,110,.24),0 0 18px rgba(255,20,70,.17)}
.gu-v4-trackbar label{display:flex;gap:3px;align-items:center;cursor:pointer}
.gu-v4-trackbar input{accent-color:#ff315c}
#gu-v4-duration{margin-left:auto;color:#f4bccb;white-space:nowrap}
.gu-v4-timeline-scroll{position:relative;width:100%;height:100%;overflow:auto;overscroll-behavior:contain;scrollbar-color:#704154 #252127;scrollbar-width:thin}
.gu-v4-timeline-content{position:relative;min-height:100%;background:#18171c}
.gu-v4-time-ruler{height:24px;position:relative;background:#25222a;border-bottom:1px solid #65414d;cursor:crosshair;user-select:none;touch-action:pan-y}
.gu-v4-ruler-mark{position:absolute;top:0;height:24px;border-left:1px solid #59515a;padding:3px 0 0 3px;color:#9c929b;font:8px var(--gu-font-tech)}
.gu-v4-lanes{position:relative;width:100%;}
.gu-v4-lane{height:53px;position:relative;display:flex;border-bottom:1px solid #4f414b;user-select:none}
.gu-v4-lane:nth-child(even){background:#201c22}.gu-v4-lane.current{background:#2a222a}
.gu-v4-lane-head{width:148px;flex:0 0 148px;background:linear-gradient(180deg,rgba(10,10,12,.98),rgba(2,2,4,.98));position:sticky;left:0;z-index:12;display:flex;align-items:center;gap:3px;border-right:2px solid #472532;padding:0 5px;box-sizing:border-box;box-shadow:3px 0 8px #08080a66}
.gu-v4-lane-title{background:transparent;color:#f4eff1;font:800 9px var(--gu-font-tech);border:0;cursor:pointer;flex:1;text-align:left;padding:4px;white-space:nowrap}
.gu-v4-lane.current .gu-v4-lane-title{color:#ff6187}
.gu-v4-mini{flex:0 0 21px;width:21px;height:21px;border:1px solid rgba(255,255,255,.12);border-radius:7px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02));color:#eadbe0;font-size:11px;cursor:pointer;padding:0;box-shadow:0 3px 10px rgba(0,0,0,.3)}
.gu-v4-mini:hover{border-color:#ff315c;box-shadow:0 0 0 1px rgba(255,60,110,.24),0 0 14px rgba(255,20,70,.16)}
.gu-v4-lane-rail{position:relative;min-width:0;height:100%;background:repeating-linear-gradient(90deg,transparent 0px,transparent 84px,#ffffff05 84px,#ffffff05 85px);cursor:crosshair}
.gu-v4-clip{position:absolute;top:4px;bottom:4px;background:#323338;border:1px solid #8d747e;border-radius:5px;overflow:hidden;cursor:grab;touch-action:none;box-sizing:border-box;box-shadow:0 2px 4px #0006;min-width:6px}
.gu-v4-lane[data-lane^="V"] .gu-v4-clip{background:#313943;border-color:#4f7286}
.gu-v4-lane[data-lane^="A"] .gu-v4-clip{background:#243934;border-color:#3b9d81}
.gu-v4-clip.selected{border:2px solid #ff315c;box-shadow:0 0 10px #ff315c75;z-index:3}
.gu-v4-clip:active{cursor:grabbing}
.gu-v4-clip-image{position:absolute;inset:0;background-position:left center;background-size:auto 100%;background-repeat:repeat-x;opacity:.8;color:#8ce1c3;font:20px monospace;white-space:nowrap;overflow:hidden}
.gu-v4-clip-label{position:absolute;bottom:1px;left:6px;right:6px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:#06060acc;color:#fff;font:800 8px var(--gu-font-tech);padding:3px 4px;pointer-events:none}
.gu-v4-trim{position:absolute;top:0;bottom:0;width:7px;background:#ffffff24;cursor:ew-resize;z-index:5;border-right:1px solid #fff5;touch-action:none}
.gu-v4-trim.left{left:0;border-left:2px solid #fff8}.gu-v4-trim.right{right:0;border-right:2px solid #fff8}
.gu-v4-trim:hover{background:#ff315ca8}
.gu-v4-head{position:absolute;top:0;bottom:0;width:2px;background:#ff1e55;z-index:20;box-shadow:0 0 9px #ff235d;cursor:ew-resize;touch-action:none;outline:none}
.gu-v4-head:after{content:'';position:absolute;left:-8px;top:24px;bottom:0;width:18px;background:transparent}
.gu-v4-head-tip{position:absolute;top:0;left:-8px;width:18px;height:20px;background:#ff2359;clip-path:polygon(0 0,100% 0,100% 55%,50% 100%,0 55%);box-shadow:0 0 10px #ff315c}
.gu-v4-head:focus-visible{background:#fff}
.gu-v4-head-info{font:800 11px var(--gu-font-tech);color:#fff;white-space:nowrap}
#gu-ve-workspace .gu-v3-toolbar{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:thin;white-space:nowrap;min-height:36px}
#gu-ve-workspace .gu-v3-toolbar button{flex-shrink:0}
#gu-ve-workspace .gu-ve-library{width:min(450px,96%);max-width:98%;box-shadow:0 18px 65px #000b}
#gu-ve-workspace .gu-ve-library-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;align-content:start;overflow-y:auto;overflow-x:hidden;padding:2px}
.gu-v4-library-card{display:flex;flex-direction:column;gap:6px;padding:7px;border:1px solid #51414c;border-radius:8px;background:#242127;min-width:0;cursor:grab}
.gu-v4-library-card:hover{border-color:#ff315c;box-shadow:0 0 10px #ff315c33}
.gu-v4-library-thumb{height:75px;display:flex;align-items:center;justify-content:center;overflow:hidden;border-radius:5px;background:#0e0f12;color:#ff5583;font-size:22px}
.gu-v4-library-thumb img{width:100%;height:100%;object-fit:cover}
.gu-v4-library-content{display:flex;flex-direction:column;gap:5px;min-width:0;color:#fff}
.gu-v4-library-name{font:700 9px var(--gu-font-tech);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.gu-v4-library-content small{font:8px var(--gu-font-tech);color:#9b99a2}
.gu-v4-library-options{display:flex;gap:3px;align-items:center;flex-wrap:wrap}
.gu-v4-library-select{flex:1;min-width:58px;max-width:100%;padding:5px 3px;border:1px solid #654857;border-radius:4px;background:#151218;color:#eee;font:8px var(--gu-font-tech)}
.gu-v4-add-media,.gu-v4-preview-media{border:1px solid #99506a;background:#39242e;color:#ff9ab5;border-radius:4px;cursor:pointer;padding:5px;font:800 8px var(--gu-font-tech)}
.gu-v4-add-media:disabled{opacity:.4;cursor:wait}
.gu-v4-add-media:hover,.gu-v4-preview-media:hover{border-color:#ff315c;color:#fff}
.gu-v4-export-backdrop{position:absolute;z-index:250;inset:0;background:#0a080cdb;display:none;justify-content:center;align-items:center;backdrop-filter:blur(12px)}
.gu-v4-export-backdrop.open{display:flex}
.gu-v4-dialog{width:min(440px,92vw);max-height:90vh;overflow:auto;display:flex;flex-direction:column;gap:12px;background:#1c1921;color:#eee;border:1px solid #cf3a67;border-radius:13px;padding:19px;box-shadow:0 14px 50px #000c;font:11px var(--gu-font-tech)}
.gu-v4-dialog-head{display:flex;align-items:center;justify-content:space-between;letter-spacing:1.5px}
.gu-v4-dialog label{display:flex;flex-direction:column;gap:6px}
.gu-v4-dialog select{background:#29242d;color:#eee;border:1px solid #604551;padding:9px;border-radius:5px}
.gu-v4-dialog p{color:#a99ba4;font-size:9px;line-height:1.5}
.gu-v4-relink{position:absolute;z-index:260;top:50%;left:50%;transform:translate(-50%,-50%);display:flex;flex-direction:column;gap:10px;width:min(460px,94vw);padding:20px;background:#201d26;color:#f7ebef;border:1px solid #ff315c;border-radius:11px;box-shadow:0 10px 50px #000;line-height:1.4}
.gu-v4-relink input{max-width:100%}
@media(max-width:900px){#gu-ve-workspace .gu-ve-header-actions .gu-v4-projectbar .gu-ve-btn{padding:6px;font-size:8px}body.gu-ve-active #gu-ve-workspace{grid-template-rows:48px minmax(0,1fr) auto auto minmax(200px,34vh)!important}}
@media(max-width:600px){#gu-ve-workspace .gu-ve-header .gu-ve-brand{font-size:8px}.gu-v4-trackbar{gap:3px;padding:3px}.gu-v4-trackbar button{font-size:8px;padding:4px}.gu-v4-library-thumb{height:58px}#gu-ve-workspace .gu-ve-library-list{grid-template-columns:repeat(2,minmax(0,1fr))}.gu-v4-library-select{min-width:52px}}
.gu-v4-inspector{margin-top:7px;width:100%;font:9px var(--gu-font-tech)}
.gu-v4-inspector-toggle{color:#eee;background:#2b242f;border:1px solid #735064;padding:6px;cursor:pointer;width:100%;font:700 9px var(--gu-font-tech);border-radius:4px}
.gu-v4-inspector-body{display:none;padding:8px;gap:6px;grid-template-columns:minmax(0,1fr) minmax(0,1fr);background:#242127;border:1px solid #503748;border-radius:5px;margin-top:3px;min-width:0}
.gu-v4-inspector.open .gu-v4-inspector-body{display:grid}
.gu-v4-inspector-body label{display:flex;flex-direction:column;gap:5px;min-width:0;color:#bdb2b9}
.gu-v4-inspector-body select,.gu-v4-inspector-body input[type=text]{width:100%;max-width:100%;color:#fff;background:#18151c;border:1px solid #5d4252;border-radius:3px;padding:5px;box-sizing:border-box}
.gu-v4-inspector-body input[type=range]{width:100%;accent-color:#ff315c}
#gu-v4-keyframe-add{grid-column:span 2;background:#37222c;color:#ffa0b9;border:1px solid #bf4470;border-radius:4px;font:800 9px var(--gu-font-tech);cursor:pointer;padding:6px}
.gu-v4-inspector-body label:last-child{grid-column:span 2}
.gu-v4-inspector.open{position:absolute;z-index:99;right:12px;bottom:14px;width:280px;max-height:55vh;overflow:auto;background:#1f1c22;border:1px solid #794358;border-radius:8px;padding:8px;box-shadow:0 10px 30px #000d}
.gu-v3-expanded .gu-v4-inspector.open{position:relative;right:auto;bottom:auto;width:100%;max-height:none}

.gu-v4-trackbar select{background:#231e26;border:1px solid #654552;color:#efeff1;font:700 9px var(--gu-font-tech);padding:4px;border-radius:4px}
.gu-v4-library-search{background:#141115;border:1px solid #674251;color:#f8dce5;padding:8px;margin:0 0 10px;border-radius:6px;font:10px var(--gu-font-tech);outline:none}
.gu-v4-library-search:focus{border-color:#ff315c}

:root{--gu-ve-accent:#ff315c;--gu-ve-accent-soft:rgba(255,49,92,.25);--gu-ve-accent-strong:rgba(255,49,92,.45);--gu-ve-button-accent:#ff315c;--gu-ve-button-accent-soft:rgba(255,49,92,.24);--gu-ve-frame-accent:#ff315c;--gu-ve-frame-accent-soft:rgba(255,49,92,.24)}
body.gu-ve-active #gu-ve-workspace .gu-ve-btn:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar button:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-mini:hover,
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn:hover,
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn.active,
body.gu-ve-active #gu-ve-workspace .gu-v4-clip.selected,
body.gu-ve-active #gu-ve-workspace .gu-v4-mini.danger:hover{border-color:var(--gu-ve-accent)!important;box-shadow:0 0 0 1px var(--gu-ve-accent-soft),0 0 18px var(--gu-ve-accent-soft)!important}
body.gu-ve-active #gu-ve-workspace .gu-ve-btn.primary{background:linear-gradient(180deg,var(--gu-ve-accent),color-mix(in srgb,var(--gu-ve-accent) 80%, #b00035));border-color:var(--gu-ve-accent);box-shadow:0 0 20px var(--gu-ve-accent-soft)}
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn span,
body.gu-ve-active #gu-ve-workspace .gu-v4-lane.current .gu-v4-lane-title,
body.gu-ve-active #gu-ve-workspace .gu-v4-head,
body.gu-ve-active #gu-ve-workspace .gu-v4-head-tip,
body.gu-ve-active #gu-ve-workspace .gu-ve-trigger:hover{color:var(--gu-ve-accent)!important}
body.gu-ve-active #gu-live-preview-wrapper{box-shadow:0 0 0 1px var(--gu-ve-accent-soft),0 0 34px var(--gu-ve-accent-soft),0 0 85px rgba(0,0,0,.4)!important}
body.gu-ve-active #gu-live-preview-wrapper:after{content:'';position:absolute;inset:-1px;border-radius:16px;pointer-events:none;box-shadow:inset 0 0 22px var(--gu-ve-accent-soft),0 0 24px var(--gu-ve-accent-soft)}
.gu-v4-head{width:2px;background:var(--gu-ve-accent)!important;box-shadow:0 0 8px var(--gu-ve-accent)}
.gu-v4-head-tip{width:14px;height:14px;left:-6px;top:4px;background:var(--gu-ve-accent)!important;clip-path:polygon(50% 100%,0 20%,100% 20%);box-shadow:0 0 10px var(--gu-ve-accent)}
.gu-v4-head:after{top:16px}
.gu-v4-color-panel{position:absolute;right:14px;top:12px;z-index:70;display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:14px;border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(18,18,21,.88),rgba(9,9,11,.8));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);box-shadow:0 8px 28px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.05)}
.gu-v4-color-panel b{font:800 9px var(--gu-font-tech);letter-spacing:1.6px;color:#f5f2f4;white-space:nowrap}
.gu-v4-color-dots{display:flex;align-items:center;gap:7px}
.gu-v4-color-dot{width:19px;height:19px;border-radius:50%;border:2px solid rgba(255,255,255,.8);cursor:pointer;box-shadow:0 0 0 1px rgba(255,255,255,.08),0 0 10px rgba(0,0,0,.25)}
.gu-v4-color-dot.active{transform:scale(1.1);box-shadow:0 0 0 2px rgba(255,255,255,.14),0 0 16px currentColor}
.gu-v4-color-save{border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.02));color:#fff;border-radius:10px;padding:7px 9px;cursor:pointer;font:800 8px var(--gu-font-tech);letter-spacing:1px}
.gu-v4-color-save:hover{border-color:var(--gu-ve-accent);box-shadow:0 0 0 1px var(--gu-ve-accent-soft),0 0 16px var(--gu-ve-accent-soft)}
.gu-v4-color-hint{font:700 8px var(--gu-font-tech);color:#bfb8be}
@media(max-width:700px){.gu-v4-color-panel{left:12px;right:auto;top:10px;max-width:calc(100% - 24px);overflow:auto}.gu-v4-color-panel b,.gu-v4-color-hint{display:none}}

body.gu-ve-active #gu-ve-workspace .gu-ve-btn:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar button:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-mini:hover,
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn:hover,
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn.active,
body.gu-ve-active #gu-ve-workspace .gu-v4-clip.selected,
body.gu-ve-active #gu-ve-workspace .gu-v4-mini.danger:hover{border-color:var(--gu-ve-button-accent)!important;box-shadow:0 0 0 1px var(--gu-ve-button-accent-soft),0 0 18px var(--gu-ve-button-accent-soft)!important}
body.gu-ve-active #gu-ve-workspace .gu-ve-btn.primary{background:linear-gradient(180deg,var(--gu-ve-button-accent),color-mix(in srgb,var(--gu-ve-button-accent) 80%, #b00035));border-color:var(--gu-ve-button-accent);box-shadow:0 0 20px var(--gu-ve-button-accent-soft)}
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn span,body.gu-ve-active #gu-ve-workspace .gu-v4-lane.current .gu-v4-lane-title{color:var(--gu-ve-button-accent)!important}
body.gu-ve-active #gu-live-preview-wrapper{box-shadow:0 0 0 1px var(--gu-ve-frame-accent-soft),0 0 34px var(--gu-ve-frame-accent-soft),0 0 85px rgba(0,0,0,.4)!important}
body.gu-ve-active #gu-live-preview-wrapper:after{content:'';position:absolute;inset:-1px;border-radius:16px;pointer-events:none;box-shadow:inset 0 0 22px var(--gu-ve-frame-accent-soft),0 0 24px var(--gu-ve-frame-accent-soft)}
.gu-v4-head{background:var(--gu-ve-frame-accent)!important;box-shadow:0 0 8px var(--gu-ve-frame-accent)}
.gu-v4-head-tip{background:var(--gu-ve-frame-accent)!important;box-shadow:0 0 10px var(--gu-ve-frame-accent)}
.gu-v4-color-panel{position:absolute;right:18px;top:16px;z-index:70;width:min(420px,calc(100% - 36px));display:flex;flex-direction:column;gap:8px;padding:10px 12px;border-radius:14px;border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(8,8,10,.9),rgba(2,2,4,.86));backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);box-shadow:0 8px 28px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.05)}
.gu-v4-color-panel.collapsed .gu-v4-color-body{display:none}
.gu-v4-color-panel .gu-v4-color-top{display:flex;align-items:center;gap:8px}
.gu-v4-color-panel .gu-v4-color-top b{flex:1}
.gu-v4-color-toggle{width:26px;height:26px;border-radius:9px;border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.02));color:#fff;cursor:pointer}
.gu-v4-color-tabs{display:flex;gap:6px;flex-wrap:wrap}
.gu-v4-color-tab{border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.03);color:#ddd;border-radius:999px;padding:5px 10px;cursor:pointer;font:800 8px var(--gu-font-tech);letter-spacing:1px}
.gu-v4-color-tab.active{border-color:var(--gu-ve-button-accent);color:#fff;box-shadow:0 0 0 1px var(--gu-ve-button-accent-soft),0 0 12px var(--gu-ve-button-accent-soft)}
.gu-v4-color-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.gu-v4-color-row label{font:800 8px var(--gu-font-tech);letter-spacing:1px;color:#cbc4ca;width:72px}
.gu-v4-color-dots{display:flex;align-items:center;gap:7px;flex-wrap:wrap;flex:1}
.gu-v4-color-actions{display:flex;gap:8px;justify-content:flex-end}
.gu-v4-color-save,.gu-v4-color-show{border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.02));color:#fff;border-radius:10px;padding:7px 9px;cursor:pointer;font:800 8px var(--gu-font-tech);letter-spacing:1px}
@media(max-width:700px){.gu-v4-color-panel{right:12px;left:12px;width:auto}}
.gu-v4-mini.danger:hover{border-color:#ff6b6b;box-shadow:0 0 0 1px rgba(255,110,110,.22),0 0 14px rgba(255,70,70,.18)}
.gu-v4-mini.disabled{opacity:.35;pointer-events:none}
.gu-v4-lane.mutedlane .gu-v4-lane-title{color:#f0ba79}
.gu-v4-lane.hiddenlane{opacity:.65}


/* ================================================================
   GRAVITY ULTRA V8 — EDICIÓN DE NEÓN POR ZONAS Y COLOR GRADING
   Pantalla = sólo halo del monitor. Botones = controles de cristal.
   Bordes = marcos generales, jamás el monitor.
   ================================================================ */
:root{
 --gu-ve-screen-accent:#ff315c;
 --gu-ve-screen-accent-soft:rgba(255,49,92,.27);
 --gu-ve-screen-accent-glow:rgba(255,49,92,.16);
 --gu-ve-outline-accent:#ff315c;
 --gu-ve-outline-accent-soft:rgba(255,49,92,.30);
 --gu-ve-outline-accent-glow:rgba(255,49,92,.13);
}
/* Color PANTALLA: sólo al contorno de la vista previa. */
body.gu-ve-active #gu-live-preview-wrapper{
 border-color:var(--gu-ve-screen-accent-soft)!important;
 box-shadow:0 0 0 1px var(--gu-ve-screen-accent-soft),0 0 34px var(--gu-ve-screen-accent-glow),0 0 76px rgba(0,0,0,.45)!important;
}
body.gu-ve-active #gu-live-preview-wrapper::after{
 box-shadow:inset 0 0 19px var(--gu-ve-screen-accent-glow),0 0 24px var(--gu-ve-screen-accent-glow)!important;
}
/* Color BORDES: paneles exteriores, zonas de trabajo y reglas del estudio.
   Se excluye expresamente la pantalla de vídeo y los botones. */
body.gu-ve-active #gu-ve-workspace{
 border-color:var(--gu-ve-outline-accent-soft)!important;
 box-shadow:0 0 0 1px var(--gu-ve-outline-accent-soft),0 0 38px var(--gu-ve-outline-accent-glow),0 18px 80px #000!important;
}
body.gu-ve-active #gu-ve-workspace .gu-ve-header,
body.gu-ve-active #gu-ve-workspace .gu-ve-left,
body.gu-ve-active #gu-ve-workspace .gu-ve-right,
body.gu-ve-active #gu-ve-workspace .gu-ve-bottom,
body.gu-ve-active #gu-ve-workspace .gu-v4-timeline-scroll,
body.gu-ve-active #gu-ve-workspace .gu-ve-ruler-stack,
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar,
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar,
body.gu-ve-active #gu-ve-workspace .gu-v4-color-panel{
 border-color:var(--gu-ve-outline-accent-soft)!important;
}
body.gu-ve-active #gu-ve-workspace .gu-ve-left,
body.gu-ve-active #gu-ve-workspace .gu-ve-right,
body.gu-ve-active #gu-ve-workspace .gu-ve-bottom,
body.gu-ve-active #gu-ve-workspace .gu-v4-color-panel{
 box-shadow:0 0 0 1px var(--gu-ve-outline-accent-soft),0 0 16px var(--gu-ve-outline-accent-glow),inset 0 1px 0 rgba(255,255,255,.04)!important;
}
/* El cursor del timeline no pertenece a los bordes: conserva su rojo original. */
body.gu-ve-active #gu-ve-workspace .gu-v4-head{
 background:#ff2359!important;
 box-shadow:0 0 9px rgba(255,35,89,.68)!important;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-head-tip{
 background:#ff2359!important;
 box-shadow:0 0 9px rgba(255,35,89,.6)!important;
}
/* Corrección de recortes en panel COLOR GRADING: distribución desde arriba,
   ruedas compactas y desplazamiento vertical de emergencia en pantallas bajas. */
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right{
 justify-content:flex-start!important;
 align-items:stretch!important;
 overflow-x:hidden!important;
 overflow-y:auto!important;
 padding:9px 9px 8px!important;
 gap:5px!important;
 scrollbar-width:thin;
 scrollbar-color:rgba(255,255,255,.25) transparent;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-panel-title{
 display:block!important;
 flex:0 0 auto!important;
 width:100%;
 min-height:18px;
 padding:2px 0 5px;
 line-height:1.35;
 text-align:center;
 white-space:normal;
 overflow:visible;
 font-size:9px;
 letter-spacing:.8px;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-wheel-grid{
 width:100%;
 flex:0 0 auto!important;
 gap:4px!important;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-wheel-wrap{
 min-height:0;
 justify-content:center;
 gap:8px;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-wheel{
 width:clamp(45px,7.2vh,69px)!important;
 height:clamp(45px,7.2vh,69px)!important;
 flex:0 0 clamp(45px,7.2vh,69px)!important;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-swatch-row{
 flex:0 0 auto!important;
 height:23px;
 min-height:23px;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-swatch{
 height:22px!important;
}
body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) #gu-ve-reset-grade{
 width:100%!important;
 min-height:31px;
 flex:0 0 auto!important;
 padding:8px 4px!important;
 font-size:8px!important;
 letter-spacing:.55px;
 white-space:nowrap;
 line-height:1.1;
 margin-bottom:3px;
}
@media(max-height:700px){
 body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right{gap:3px!important;padding-top:6px!important;padding-bottom:6px!important}
 body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-wheel{
  width:40px!important;height:40px!important;flex-basis:40px!important;
 }
 body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-swatch-row{height:20px;min-height:20px}
 body.gu-ve-active #gu-ve-workspace:not(.gu-v3-expanded) .gu-ve-right .gu-ve-swatch{height:19px!important}
}


/* ========================================================================
 GRAVITY ULTRA V9 — CRYSTAL POLISH: SOLO ACABADOS Y PRESENTACIÓN
 La estructura y funciones originales V8 permanecen. Tres LED independientes:
 Pantalla = monitor; Botones = interacción; Bordes = armazón del estudio.
 ======================================================================== */
body.gu-ve-active #gu-ve-workspace{
 background:#030304!important;
 --gu-v9-frost:rgba(255,255,255,.035);
 --gu-v9-glint:rgba(255,255,255,.10);
 --gu-v9-stroke:rgba(255,255,255,.12);
}
body.gu-ve-active #gu-ve-workspace .gu-ve-header,
body.gu-ve-active #gu-ve-workspace .gu-ve-left,
body.gu-ve-active #gu-ve-workspace .gu-ve-right,
body.gu-ve-active #gu-ve-workspace .gu-ve-bottom,
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar,
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar{
 background:linear-gradient(160deg,rgba(25,25,30,.56),rgba(5,5,8,.91) 58%,rgba(0,0,0,.97))!important;
 -webkit-backdrop-filter:blur(15px) saturate(115%);
 backdrop-filter:blur(15px) saturate(115%);
 box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 12px 28px rgba(0,0,0,.3);
}
/* Reflejo superior discreto sin cubrir botones o interacciones */
body.gu-ve-active #gu-ve-workspace .gu-ve-left,
body.gu-ve-active #gu-ve-workspace .gu-ve-right,
body.gu-ve-active #gu-ve-workspace .gu-ve-bottom{position:relative;}
body.gu-ve-active #gu-ve-workspace .gu-ve-left::before,
body.gu-ve-active #gu-ve-workspace .gu-ve-right::before,
body.gu-ve-active #gu-ve-workspace .gu-ve-bottom::before{
 content:"";pointer-events:none;position:absolute;inset:0 0 auto 0;height:32px;
 border-radius:inherit;
 background:linear-gradient(180deg,rgba(255,255,255,.046),transparent);
}
/* Vidrio negro: nunca plomo sólido */
body.gu-ve-active #gu-ve-workspace .gu-ve-btn,
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn,
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar button,
body.gu-ve-active #gu-ve-workspace .gu-v3-tool,
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar button,
body.gu-ve-active #gu-ve-workspace .gu-v4-mini,
body.gu-ve-active #gu-ve-workspace .gu-v4-color-tab,
body.gu-ve-active #gu-ve-workspace .gu-v4-color-toggle,
body.gu-ve-active #gu-ve-workspace .gu-v4-inspector-toggle,
body.gu-ve-active #gu-ve-workspace .gu-v4-add-media,
body.gu-ve-active #gu-ve-workspace .gu-v4-preview-media{
 border-radius:10px;
 border:1px solid rgba(255,255,255,.14);
 background:linear-gradient(165deg,rgba(255,255,255,.102) 0%,rgba(255,255,255,.045) 39%,rgba(255,255,255,.012) 95%);
 color:#f1edf2;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.115),0 3px 11px rgba(0,0,0,.28);
 transition:background-color .22s ease,border-color .22s ease,box-shadow .22s ease,color .22s ease,transform .22s ease;
}
body.gu-ve-active #gu-ve-workspace .gu-ve-btn:hover:not(:disabled),
body.gu-ve-active #gu-ve-workspace .gu-ve-sidebtn:hover,
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar button:hover:not(:disabled),
body.gu-ve-active #gu-ve-workspace .gu-v3-tool:hover:not(:disabled),
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar button:hover:not(:disabled),
body.gu-ve-active #gu-ve-workspace .gu-v4-mini:hover:not(:disabled),
body.gu-ve-active #gu-ve-workspace .gu-v4-inspector-toggle:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-color-tab:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-add-media:hover,
body.gu-ve-active #gu-ve-workspace .gu-v4-preview-media:hover{
 border-color:var(--gu-ve-button-accent)!important;
 color:#fff;
 background:linear-gradient(160deg,rgba(255,255,255,.145),rgba(255,255,255,.035));
 box-shadow:inset 0 1px 0 rgba(255,255,255,.15),0 0 0 1px var(--gu-ve-button-accent-soft),0 0 19px var(--gu-ve-button-accent-soft)!important;
 transform:translateY(-1px);
}
body.gu-ve-active #gu-ve-workspace button:active:not(:disabled){transform:translateY(0);}
body.gu-ve-active #gu-ve-workspace button:focus-visible,
body.gu-ve-active #gu-ve-workspace .gu-v4-clip:focus-visible{
 outline:2px solid var(--gu-ve-button-accent);outline-offset:2px;
}
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar{padding:8px 10px;gap:5px;min-height:43px;}
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar button{min-height:30px;padding:6px 10px;font-size:10px;}
body.gu-ve-active #gu-ve-workspace .gu-v3-toolbar button:disabled{opacity:.34;box-shadow:none;filter:saturate(.5);}
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar{padding:7px 12px;gap:7px;}
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar button{min-height:27px;}
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar select{
 border-radius:8px;border:1px solid var(--gu-v9-stroke);
 background:#09090e;color:#f4eef2;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.07);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-trackbar input[type="checkbox"]{accent-color:var(--gu-ve-button-accent);}
/* Timeline: reglas precisas, pistas mate negras, bordes finos */
body.gu-ve-active #gu-ve-workspace .gu-v4-timeline-scroll,
body.gu-ve-active #gu-ve-workspace .gu-ve-ruler-stack{
 background:#060609!important;
 border-radius:12px;
 scrollbar-color:rgba(180,180,195,.38) rgba(10,10,14,.5);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-timeline-content,
body.gu-ve-active #gu-ve-workspace .gu-v4-lanes{background:#09090d!important;}
body.gu-ve-active #gu-ve-workspace .gu-v4-time-ruler{
 background:linear-gradient(180deg,#16141b,#100f15);
 border-bottom:1px solid rgba(255,255,255,.12);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-ruler-mark{
 color:#aaa9b5;
 border-left:1px solid rgba(255,255,255,.13);
 font-size:8px;letter-spacing:.35px;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane{
 background:linear-gradient(180deg,#111015,#0b0b0f)!important;
 border-bottom:1px solid rgba(255,255,255,.082);
 transition:background .2s ease;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane:nth-child(even){background:linear-gradient(180deg,#0e0e12,#09090d)!important;}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane.current{
 background:linear-gradient(90deg,var(--gu-ve-button-accent-soft) -30%,#131119 21%,#0d0d11 100%)!important;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane-head{
 background:linear-gradient(140deg,#131218,#050507 80%)!important;
 border-right:1px solid var(--gu-v9-stroke);
 box-shadow:3px 0 12px #000b,inset 0 1px 0 rgba(255,255,255,.035);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane-title{
 font-size:10px;letter-spacing:.45px;color:#dcd9e1;
 min-width:27px;padding:4px 1px;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane-rail{
 background-image:repeating-linear-gradient(90deg,transparent 0,transparent 84px,rgba(255,255,255,.038) 84px,rgba(255,255,255,.038) 85px);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane[data-lane^="A"] .gu-v4-lane-rail{
 background-color:rgba(7,21,20,.36);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-mini{
 width:21px;height:22px;flex-basis:21px;border-radius:7px;
 padding:0;display:inline-flex;align-items:center;justify-content:center;
 font-size:11px;line-height:1;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-mini svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;pointer-events:none;}
body.gu-ve-active #gu-ve-workspace .gu-v4-mini.danger:hover{border-color:#ff637f!important;box-shadow:0 0 14px rgba(255,55,99,.27)!important;}
body.gu-ve-active #gu-ve-workspace .gu-v4-mini.disabled{opacity:.32;box-shadow:none;}
/* Clips de vídeo: marco grafito azul, miniaturas y focos precisos */
body.gu-ve-active #gu-ve-workspace .gu-v4-clip{
 border-radius:6px;overflow:hidden;
 border:1px solid rgba(255,255,255,.24);
 background:linear-gradient(180deg,#22252e,#151720);
 box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 2px 10px #0009;
 transition:border-color .2s ease,box-shadow .2s ease,filter .2s ease;
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane[data-lane^="V"] .gu-v4-clip{
 background:linear-gradient(180deg,#263341,#141b25);
 border-color:rgba(123,174,215,.42);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-lane[data-lane^="A"] .gu-v4-clip{
 background:linear-gradient(180deg,#153f3a,#0a2926);
 border-color:rgba(70,218,182,.46);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-clip:hover{
 filter:brightness(1.13);
 box-shadow:inset 0 1px 0 rgba(255,255,255,.17),0 0 12px rgba(255,255,255,.12);
}
body.gu-ve-active #gu-ve-workspace .gu-v4-clip.selected,
body.gu-ve-active #gu-ve-workspace .gu-v4-lane[data-lane] .gu-v4-clip.selected{
 border:2px solid var(--gu-ve-button-accent)!important;
