/* V12 conservadora: extensiones Studio, no modifica el sistema visual original */
#gu-ve-workspace .gu-v12-preview{display:none;position:fixed;inset:0;z-index:2147483000;align-items:center;justify-content:center;flex-direction:column;gap:12px;background:rgba(0,0,0,.92);padding:24px;color:#fff;backdrop-filter:blur(15px)}
#gu-ve-workspace .gu-v12-preview.open{display:flex}
#gu-ve-workspace .gu-v12-preview-head{width:min(90vw,820px);display:flex;gap:18px;justify-content:space-between;align-items:center;font:700 11px var(--gu-font-tech);letter-spacing:1.5px}
#gu-ve-workspace .gu-v12-preview-head button{background:rgba(255,0,51,.10);border:1px solid var(--gu-neon);border-radius:8px;color:#fff;cursor:pointer;padding:10px 15px}
#gu-ve-workspace .gu-v12-preview-media{width:min(90vw,820px);min-height:120px;max-height:75vh;background:#09090b;border:1px solid rgba(255,255,255,.12);border-radius:12px;display:flex;align-items:center;justify-content:center;overflow:hidden;box-shadow:0 0 35px rgba(0,0,0,.9)}
#gu-ve-workspace .gu-v12-preview-media video,#gu-ve-workspace .gu-v12-preview-media img{width:100%;max-height:75vh;object-fit:contain}
#gu-ve-workspace .gu-v12-preview-media audio{width:90%;min-height:80px}
#gu-v12-preview-name{color:rgba(255,255,255,.70);max-width:90vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:10px var(--gu-font-tech)}
#gu-ve-workspace .gu-v12-text-controls{display:none;grid-column:1 / -1;padding:9px;border:1px solid rgba(255,255,255,.1);border-radius:10px;background:rgba(0,0,0,.18);font:9px var(--gu-font-tech)}
#gu-ve-workspace .gu-v12-text-controls.visible{display:block}
#gu-ve-workspace .gu-v12-text-controls strong{display:block;letter-spacing:1.2px;margin-bottom:10px;color:var(--gu-neon)}
