/* GRAVITY V14: extensiones no destructivas; conserva estética Galaxy. */
.gu-v14-solo-active,.gu-v14-mix-solo.active{color:#ff4566 !important;border-color:var(--gu-neon) !important;box-shadow:0 0 7px rgba(255,0,51,.35)}
.gu-v14-mixer{margin-top:7px;border:1px solid rgba(255,255,255,.10);border-radius:8px;background:rgba(0,0,0,.35);color:#fff;max-width:100%}
.gu-v14-mixer-toggle{width:100%;min-height:28px;padding:7px;background:transparent;color:#fff;border:0;cursor:pointer;font:700 9px var(--gu-font-tech);letter-spacing:1px;text-align:left}
.gu-v14-mixer-body{padding:9px;max-height:190px;overflow:auto}.gu-v14-mixer-body[hidden]{display:none !important}
.gu-v14-mix-row{display:grid;grid-template-columns:24px minmax(55px,1fr) 41px 20px;gap:5px;align-items:center;margin:5px 0;font:700 9px var(--gu-font-tech)}
.gu-v14-mix-row input{width:100%;accent-color:var(--gu-neon)}.gu-v14-mix-value{color:#ddd;text-align:right;font-size:8px}
.gu-v14-mix-solo{border:1px solid rgba(255,255,255,.2);border-radius:4px;background:#090909;color:#fff;cursor:pointer;height:21px}
#gu-v14-reset-color{padding:7px;border:1px solid rgba(255,255,255,.17);background:transparent;color:#ddd;cursor:pointer;font:700 8px var(--gu-font-tech)}
#gu-v14-reset-color:hover,#gu-v14-linked-move:hover{border-color:var(--gu-neon);color:var(--gu-neon)}
.gu-v14-mix-row:focus-within{outline:1px solid var(--gu-neon);outline-offset:2px}

.gu-v14-marker{position:absolute;top:3px;transform:translateX(-50%);border:none;background:transparent;color:var(--gu-neon);text-shadow:0 0 7px var(--gu-neon);z-index:6;cursor:pointer;padding:0 3px;font-size:15px}
.gu-v14-marker:hover{color:#fff}.gu-v14-marker:focus-visible{outline:2px solid var(--gu-neon)}
.gu-v14-marker-control{border:1px solid rgba(255,255,255,.13);border-radius:9px;padding:6px;color:#ddd;background:rgba(3,3,3,.55);font:700 9px var(--gu-font-tech);cursor:pointer}
.gu-v14-marker-control:hover{border-color:var(--gu-neon);color:var(--gu-neon)}

/* V15/V16 integración no destructiva: controles usan la tipografía y estética Galaxy existentes */
#gu-v15-ripple-all,#gu-v16-preview-proxy{font-family:var(--gu-font-tech);letter-spacing:.6px;white-space:nowrap}
#gu-v15-ripple-all:focus-visible,#gu-v16-preview-proxy:focus-visible{outline:2px solid var(--gu-neon);outline-offset:2px}

/* V18: paneles complementarios Galaxy; NO sustituye ningún estilo anterior. */
#gu-ve-workspace .gu-v18-suite{margin-top:8px;border:1px solid rgba(255,255,255,.13);border-radius:9px;background:rgba(0,0,0,.34);color:#fff;font:9px var(--gu-font-tech);min-width:0}
#gu-ve-workspace .gu-v18-suite>summary{cursor:pointer;padding:9px 8px;font-weight:800;letter-spacing:1px;color:var(--gu-neon)}
#gu-ve-workspace .gu-v18-suite .gu-v18-body{padding:7px 9px 11px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
#gu-ve-workspace .gu-v18-suite label{display:flex;flex-direction:column;gap:4px;min-width:0;color:rgba(255,255,255,.76);font-size:8px}
#gu-ve-workspace .gu-v18-suite input,#gu-ve-workspace .gu-v18-suite select{box-sizing:border-box;width:100%;min-width:0;padding:6px 4px;color:#fff;background:#171519;border:1px solid rgba(255,255,255,.18);border-radius:5px;font:10px var(--gu-font-tech)}
#gu-ve-workspace .gu-v18-suite input[type=range]{padding:0;accent-color:var(--gu-neon)}
#gu-ve-workspace .gu-v18-suite button{background:#191419;color:#eee;border:1px solid rgba(255,255,255,.2);border-radius:6px;min-height:29px;padding:5px;cursor:pointer;font:800 8px var(--gu-font-tech)}
#gu-ve-workspace .gu-v18-suite button:hover,#gu-ve-workspace .gu-v18-suite button:focus-visible{color:var(--gu-neon);border-color:var(--gu-neon)}
#gu-ve-workspace .gu-v18-suite button:disabled{opacity:.3;cursor:not-allowed}
#gu-ve-workspace .gu-v18-wide{grid-column:1/-1}
#gu-ve-workspace .gu-v18-notice{font-size:8px;color:#b8aeb3;line-height:1.5;grid-column:1/-1}
#gu-ve-workspace .gu-v18-histogram{width:100%;height:56px;background:#09090d;border:1px solid #3a2b34;border-radius:4px;display:block;grid-column:1/-1}
#gu-ve-workspace .gu-v18-recovery{display:flex;flex-wrap:wrap;gap:5px;align-items:center}
#gu-ve-workspace .gu-v18-recovery select{min-width:112px;max-width:170px;color:#fff;background:#171519;border:1px solid #604250;font:9px var(--gu-font-tech)}
#gu-ve-workspace .gu-v18-recovery button{cursor:pointer}
#gu-ve-workspace .gu-v18-badge{color:#cfbac1;font:8px var(--gu-font-tech)}
@media(max-width:730px){#gu-ve-workspace .gu-v18-suite .gu-v18-body{grid-template-columns:minmax(0,1fr)}}

body.script:
//
// Reproductor PC extraído del tema original. Solo se inicializa el reproductor visible.
(function(){'use strict';
const $=id=>document.getElementById(id);
const root=$('gu-live-preview-wrapper'), video=$('gu-live-video'), ui=$('gu-live-ui-layer');
if(!root||!video)return;
const p=new URLSearchParams(location.search);
const title=$('gu-live-movie-title'), tags=$('gu-live-movie-tags'), info=$('gu-live-movie-info');
const fileInput=$('gu-local-video-file');
let engine=null,engineType='',activeFilter='',sharpness=100,editing=false,hideTimer,sourceGeneration=0;
const ownedSources=new Map();
let sourceInfo={url:'',file:null,label:'',streaming:false},studioDisplay={playing:false,time:0,duration:0,volume:1};
const bridge=()=>window.guStudioBridge;
const studioOwns=()=>!!bridge()?.ownsPlayback?.();
const controlsBusy=()=>!!bridge()?.isBusy?.();
const safeUrl=s=>{try{const u=new URL(s,location.href);return ['https:','http:','blob:'].includes(u.protocol)?u.href:null}catch{return null}};
const unit=v=>Math.max(0,Math.min(1,Number(v)||0));
const fmt=s=>{if(!Number.isFinite(s))return '00:00';const n=Math.max(0,Math.floor(s));return Math.floor(n/3600)?`${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`:`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`};
function playerError(message){if(studioOwns())return;$('gu-live-quality-label').textContent=message;const out=$('gu-ve-status');if(out)out.textContent=message;showUI()}
function seekWindow(){const d=video.duration;if(Number.isFinite(d)&&d>0)return {start:0,end:d};try{const s=video.seekable;if(s?.length)return {start:s.start(0),end:s.end(s.length-1)}}catch{}return null}
function syncVolume(){const value=studioOwns()?unit(bridge()?.getVolume?.()??studioDisplay.volume):(video.muted?0:video.volume);$('gu-live-vol-slider').value=value;$('gu-live-btn-mute').setAttribute('aria-pressed',String(value===0));$('gu-live-btn-mute').setAttribute('aria-label',value===0?'Activar sonido':'Silenciar sonido')}
function displayPlayback(isPlaying,time,duration,ratio){$('gu-live-center-clock').textContent=fmt(time);$('gu-live-center-status').textContent=isPlaying?'PLAYING':'PAUSE';$('gu-live-time-tracker').textContent=fmt(time)+' / '+(Number.isFinite(duration)?fmt(duration):'EN DIRECTO');$('gu-live-progress-fill').style.width=(unit(ratio)*100)+'%';const progress=$('gu-live-progress-container');progress.setAttribute('aria-valuenow',String(Math.round(unit(ratio)*100)));progress.setAttribute('aria-valuetext',fmt(time));$('gu-live-btn-play').setAttribute('aria-label',isPlaying?'Pausar':'Reproducir');$('gu-live-btn-play').setAttribute('aria-pressed',String(isPlaying))}
function update(){if(studioOwns())return;const bounds=seekWindow(),time=Number.isFinite(video.currentTime)?video.currentTime:0;displayPlayback(!video.paused,time,video.duration||0,bounds?(time-bounds.start)/Math.max(.001,bounds.end-bounds.start):0)}
function releaseUnusedSources(inUseUrls){const used=new Set(inUseUrls||[]);if(sourceInfo.url)used.add(sourceInfo.url);if(video.currentSrc)used.add(video.currentSrc);for(const url of ownedSources.keys()){if(!used.has(url)){URL.revokeObjectURL(url);ownedSources.delete(url)}}}
function setSource(url,label,file){
 const src=safeUrl(url);if(!src){playerError('DIRECCIÓN DE VIDEO NO VÁLIDA');return false}
 if(controlsBusy()){const out=$('gu-ve-status');if(out)out.textContent='TERMINA O CANCELA LA EXPORTACIÓN ANTES DE CAMBIAR DE VIDEO';return false}
 if(bridge()?.onSourceChange?.()===false)return false;
 const generation=++sourceGeneration;
 if(engine){try{engine.destroy()}catch(error){console.warn('Cierre del motor de reproducción',error)}engine=null}
 engineType='';video.pause();video.removeAttribute('src');video.load();
 sourceInfo={url:src,file:file||ownedSources.get(src)||null,label:label||title.textContent,streaming:/\.(m3u8|mpd)(?:[?#]|$)/i.test(src)};
 const refresh=()=>{if(generation===sourceGeneration){updateMenus();update()}};
 try{
  if(/\.m3u8(?:[?#]|$)/i.test(src)&&window.Hls?.isSupported?.()){
   const instance=new window.Hls({enableWorker:true});engine=instance;engineType='hls';const events=window.Hls.Events;
   instance.on(events.MEDIA_ATTACHED,()=>{if(generation===sourceGeneration)instance.loadSource(src)});
   for(const key of ['MANIFEST_PARSED','LEVELS_UPDATED','LEVEL_SWITCHED','AUDIO_TRACKS_UPDATED','AUDIO_TRACK_SWITCHED','SUBTITLE_TRACKS_UPDATED','SUBTITLE_TRACK_SWITCH'])if(events[key])instance.on(events[key],refresh);
   instance.on(events.ERROR,(_event,data)=>{if(generation!==sourceGeneration||!data?.fatal)return;video.pause();playerError('ERROR DE TRANSMISIÓN · VUELVE A CARGAR LA FUENTE');update()});
   instance.attachMedia(video);
  }else if(/\.mpd(?:[?#]|$)/i.test(src)&&window.dashjs?.MediaPlayer){
   const instance=window.dashjs.MediaPlayer().create();engine=instance;engineType='dash';
   const events=window.dashjs.MediaPlayer.events||{};
   for(const event of new Set([events.STREAM_INITIALIZED||'streamInitialized',events.TRACK_CHANGE_RENDERED||'trackChangeRendered',events.TEXT_TRACKS_ADDED||'allTextTracksAdded',events.QUALITY_CHANGE_RENDERED||'qualityChangeRendered']))instance.on(event,refresh);
   instance.on(events.ERROR||'error',()=>{if(generation===sourceGeneration)playerError('ERROR DE TRANSMISIÓN DASH')});
   instance.initialize(video,src,false);
  }else{
   if(/\.mpd(?:[?#]|$)/i.test(src)||/\.m3u8(?:[?#]|$)/i.test(src)&&!video.canPlayType('application/vnd.apple.mpegurl'))playerError('MOTOR DE STREAMING NO DISPONIBLE · REVISA LA CONEXIÓN');
   video.src=src;
  }
 }catch(error){playerError('NO SE PUDO CARGAR EL VIDEO');console.warn('Carga del reproductor',error)}
 if(label){title.textContent=label;tags.textContent=''}
 update();updateMenus();syncVolume();
 window.dispatchEvent(new CustomEvent('gu:source',{detail:{...sourceInfo}}));
 if(!bridge())releaseUnusedSources([]);
 return true;
}
window.guEditorSetVideoSource=setSource;
let guLocalFileTicket=0;
async function selectLocalFile(f){
 if(!f||controlsBusy())return;const ticket=++guLocalFileTicket;
 try{if(bridge()?.validateMediaFile)await bridge().validateMediaFile(f,'video');
  if(ticket!==guLocalFileTicket||controlsBusy())return;const url=URL.createObjectURL(f);ownedSources.set(url,f);
  if(!setSource(url,f.name.replace(/\.[^.]+$/,''),f)){URL.revokeObjectURL(url);ownedSources.delete(url)}
 }catch(error){playerError(error?.message||'NO SE PUDO ABRIR EL ARCHIVO')}
}
fileInput.addEventListener('change',()=>{const f=fileInput.files?.[0];fileInput.value='';selectLocalFile(f)});
root.addEventListener('dragover',e=>{if(e.dataTransfer&&Array.from(e.dataTransfer.types).includes('Files'))e.preventDefault()});
root.addEventListener('drop',e=>{if(bridge()?.isEditing?.())return;const f=e.dataTransfer&&Array.from(e.dataTransfer.files).find(x=>x.type.startsWith('video/')||/\.(mp4|mov|webm|mkv|m4v|ogv)$/i.test(x.name));if(f){e.preventDefault();selectLocalFile(f)}});
const playBtn=$('gu-live-btn-play');
function showUI(){ui.classList.remove('gu-ui-hidden');root.classList.remove('gu-cursor-hidden');clearTimeout(hideTimer);const isPlaying=studioOwns()?studioDisplay.playing:!video.paused;if(isPlaying)hideTimer=setTimeout(()=>{if(!editing&&!root.contains(document.activeElement)){ui.classList.add('gu-ui-hidden');root.classList.add('gu-cursor-hidden')}},2500)}
function togglePlay(){if(controlsBusy())return;if(studioOwns()){bridge()?.togglePlay?.();showUI();return}if(!video.currentSrc&&!engine){fileInput.click();return}if(video.paused){const generation=sourceGeneration;const result=video.play();result?.catch(error=>{if(generation!==sourceGeneration||studioOwns()||error?.name==='AbortError')return;video.pause();playerError('NO SE PUDO REPRODUCIR · '+(error?.message||'REVISA EL ARCHIVO'));update()})}else video.pause()}
playBtn.addEventListener('click',e=>{e.stopPropagation();togglePlay()});video.addEventListener('click',togglePlay);root.addEventListener('pointermove',showUI);root.addEventListener('focusin',showUI);
video.addEventListener('play',()=>{if(!studioOwns()){update();showUI()}});
video.addEventListener('pause',()=>{if(!studioOwns()){update();showUI()}});
video.addEventListener('ended',()=>{if(!studioOwns()){update();showUI()}});
video.addEventListener('loadedmetadata',()=>{if(!studioOwns()){const h=video.videoHeight||0;$('gu-live-quality-label').textContent=h>=4000?'8K ULTRA HD':h>=2100?'4K ULTRA HD':h>=1000?'1080p FULL HD':h>=700?'720p HD':h?`${h}p`:'ANALIZANDO...';update()}updateMenus()});
video.addEventListener('timeupdate',update);video.addEventListener('durationchange',update);video.addEventListener('error',()=>playerError('ERROR DE VIDEO · FORMATO O FUENTE NO DISPONIBLE'));
for(const tracks of [video.textTracks,video.audioTracks])if(tracks?.addEventListener)for(const event of ['addtrack','removetrack','change'])tracks.addEventListener(event,updateMenus);
const progress=$('gu-live-progress-container');let dragging=false;
progress.setAttribute('role','slider');progress.tabIndex=0;progress.setAttribute('aria-label','Posición de reproducción');progress.setAttribute('aria-valuemin','0');progress.setAttribute('aria-valuemax','100');
function seekRatio(value){if(controlsBusy())return;const ratio=unit(value);if(studioOwns()){bridge()?.seekRatio?.(ratio);showUI();return}const bounds=seekWindow();if(!bounds)return;try{video.currentTime=Math.min(bounds.end-.001,Math.max(bounds.start,bounds.start+ratio*(bounds.end-bounds.start)))}catch(error){playerError('NO SE PUEDE BUSCAR EN ESTA FUENTE')}update()}
function seek(e){const rect=progress.getBoundingClientRect();if(rect.width>0)seekRatio((e.clientX-rect.left)/rect.width)}
progress.addEventListener('pointerdown',e=>{if(controlsBusy()||e.button>0||!studioOwns()&&!seekWindow())return;e.preventDefault();e.stopPropagation();dragging=true;progress.setPointerCapture(e.pointerId);seek(e)});
progress.addEventListener('pointermove',e=>{if(dragging)seek(e)});
for(const event of ['pointerup','pointercancel','lostpointercapture'])progress.addEventListener(event,()=>{dragging=false});
progress.addEventListener('click',e=>{e.preventDefault();e.stopPropagation()});
progress.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const bounds=seekWindow(),fraction=studioOwns()?(studioDisplay.time/Math.max(.001,studioDisplay.duration)):(bounds?(video.currentTime-bounds.start)/(bounds.end-bounds.start):0);seekRatio(e.key==='Home'?0:e.key==='End'?1:fraction+(e.key==='ArrowLeft'?-1:1)*.01)});
$('gu-live-vol-slider').addEventListener('input',e=>{if(controlsBusy()){syncVolume();return}const value=unit(e.target.value);if(studioOwns())bridge()?.setVolume?.(value);else {video.volume=value;video.muted=value===0}syncVolume()});
$('gu-live-btn-mute').addEventListener('click',()=>{if(controlsBusy())return;if(studioOwns())bridge()?.toggleMute?.();else {if(video.muted||video.volume===0){if(video.volume===0)video.volume=1;video.muted=false}else video.muted=true}syncVolume()});
video.addEventListener('volumechange',()=>{if(!studioOwns())syncVolume()});
$('gu-live-btn-fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(root.requestFullscreen)await root.requestFullscreen();else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen()}catch(error){playerError('NO SE PUDO ACTIVAR PANTALLA COMPLETA')}});
document.addEventListener('keydown',e=>{if(e.defaultPrevented||e.repeat||studioOwns()||e.target.closest('input,select,textarea,button,a,[role="button"],[role="slider"],[contenteditable="true"]'))return;if(e.code==='Space'&&(document.activeElement===document.body||root.contains(document.activeElement))){e.preventDefault();togglePlay()}});
function accessibleControl(el,label){if(!el||el.matches('button,input,select,textarea,a'))return;el.setAttribute('role','button');el.tabIndex=0;if(!el.getAttribute('aria-label'))el.setAttribute('aria-label',label||el.title||el.textContent.trim()||'Control');if(el.dataset.guKeyboard==='1')return;el.dataset.guKeyboard='1';el.addEventListener('keydown',e=>{if(e.code==='Space'||e.key==='Enter'){e.preventDefault();e.stopPropagation();if(!e.repeat&&el.getAttribute('aria-disabled')!=='true')el.click()}})}
window.guPlayer={setSource,getSourceInfo:()=>({...sourceInfo}),getCurrentFile:()=>sourceInfo.file,releaseUnusedSources,syncControls:()=>{syncVolume();update();showUI()},setStudioDisplay:values=>{const wasPlaying=studioDisplay.playing;studioDisplay={...studioDisplay,...values};if(!studioOwns())return;displayPlayback(!!studioDisplay.playing,studioDisplay.time,studioDisplay.duration,studioDisplay.duration?studioDisplay.time/studioDisplay.duration:0);syncVolume();if(wasPlaying!==studioDisplay.playing)showUI()}};
window.guScrollCarousel=(el,dir)=>el.parentElement.querySelector('.gu-color-row')?.scrollBy({left:dir*120,behavior:'smooth'});
window.guSetColor=(el,hex)=>{if(!/^#[0-9a-f]{6}$/i.test(hex))return;document.documentElement.style.setProperty('--gu-neon',hex);root.querySelectorAll('.gu-btn-color').forEach(x=>x.classList.toggle('active',x===el))};
window.guToggleDropdown=id=>{const el=$(id);if(el)el.style.display=el.style.display==='flex'?'none':'flex'};
window.guSelectOption=(parent,val)=>{const key=parent.id;if(key.endsWith('aud-drop'))selectAudio(val);else if(key.endsWith('sub-drop'))selectSubtitle(val);else if(key.endsWith('qual-drop'))selectQuality(val);parent.style.display='none'};
window.guToggleLiveRightDock=btn=>{const panel=$('gu-live-panel-glass'),tubes=$('gu-live-glass-tubes'),close=!panel.classList.contains('hidden-panel');panel.classList.toggle('hidden-panel',close);tubes.classList.toggle('hidden-tubes',close);btn.setAttribute('aria-expanded',String(!close))};
function applyFilter(){let f='contrast(1) saturate(1)';if(sharpness<100)f+=` blur(${(100-sharpness)/40}px)`;if(sharpness>100)f+=` contrast(${1+(sharpness-100)/200}) saturate(${1+(sharpness-100)/200})`;const tint=$('gu-live-cinematic-tint');if(activeFilter==='grayscale'){f+=' grayscale(1)';tint.style.opacity=0}else if(activeFilter){tint.style.backgroundColor=activeFilter;tint.style.opacity='.5';tint.style.mixBlendMode='color'}else tint.style.opacity=0;video.style.filter=f}
window.guSetFilter=(el,value)=>{activeFilter=value;root.querySelectorAll('.gu-cinematic-dot').forEach(x=>x.classList.toggle('active',x===el));applyFilter()};
$('gu-live-sharpness-slider').addEventListener('input',e=>{sharpness=Number(e.target.value);applyFilter()});
const catFonts={empresarial:['Inter','Montserrat','Roboto','Poppins','Oswald','Raleway','Lato','Space Grotesk','Orbitron','Bebas Neue','Anton','Archivo Black','Titillium Web'],cine:['Cinzel','Playfair Display','Bodoni Moda','Abril Fatface','Merriweather','Prata','Great Vibes','Cormorant Garamond','Tangerine','Cinzel Decorative'],animacion:['Fredoka One','Bangers','Chewy','Audiowide','Luckiest Guy','Bungee','Comic Neue','Press Start 2P','Creepster','Righteous','Rubik Bubbles','Sigmar']};
let cat='empresarial',fontIndex=0;
window.guSetCategory=(name)=>{cat=name;fontIndex=0;root.querySelectorAll('.gu-cat-btn').forEach(b=>b.classList.toggle('active',b.textContent.trim().toLowerCase().startsWith(name==='cine'?'cinematografía':name==='animacion'?'animación':'empresarial')));applyFont()};
window.guChangeFont=delta=>{fontIndex=(fontIndex+delta+catFonts[cat].length)%catFonts[cat].length;applyFont()};
function applyFont(){title.style.fontFamily=`'${catFonts[cat][fontIndex]}',sans-serif`;title.classList.remove('gu-font-transitioning');void title.offsetWidth;title.classList.add('gu-font-transitioning')}
// Selector de pistas: sólo activa pistas disponibles, nunca simula idiomas o resoluciones inexistentes.
function trackOption(parent,label,run){const option=document.createElement('span');option.className='gu-drop-opt';option.textContent=label;if(run){accessibleControl(option,label);option.addEventListener('click',()=>{if(controlsBusy())return;run();parent.style.display='none';updateMenus()})}parent.appendChild(option);return option}
function nativeSubtitle(index){for(let i=0;i<video.textTracks.length;i++)video.textTracks[i].mode=i===index?'showing':'disabled'}
function updateMenus(){
 const q=$('gu-live-qual-drop'),a=$('gu-live-aud-drop'),s=$('gu-live-sub-drop');if(!q||!a||!s)return;
 q.replaceChildren();a.replaceChildren();s.replaceChildren();
 const instance=engine;
 if(engineType==='hls'&&instance?.levels?.length){trackOption(q,'AUTO',()=>{if(engine===instance)instance.currentLevel=-1});instance.levels.forEach((level,i)=>trackOption(q,level.height?level.height+'p':'NIVEL '+(i+1),()=>{if(engine===instance)instance.currentLevel=i}))}
 else trackOption(q,engineType==='dash'?'AUTO (DASH)':'CALIDAD DEL ARCHIVO ORIGINAL');
 let audioTracks=[],subtitleTracks=[];
 if(engineType==='hls'&&instance){audioTracks=instance.audioTracks||[];subtitleTracks=instance.subtitleTracks||[]}
 if(engineType==='dash'&&instance?.getTracksFor){try{audioTracks=instance.getTracksFor('audio')||[];subtitleTracks=instance.getTracksFor('text')||[]}catch{}}
 if(audioTracks.length>1){audioTracks.forEach((track,i)=>trackOption(a,track.name||track.lang||track.labels?.[0]?.text||'PISTA '+(i+1),()=>{if(instance!==engine)return;if(engineType==='hls')instance.audioTrack=i;else instance.setCurrentTrack?.(track)}))}
 else if(video.audioTracks?.length>1){for(let i=0;i<video.audioTracks.length;i++){const track=video.audioTracks[i];trackOption(a,track.label||track.language||'PISTA '+(i+1),()=>{for(let j=0;j<video.audioTracks.length;j++)video.audioTracks[j].enabled=j===i})}}
 else trackOption(a,'AUDIO ORIGINAL');
 if(subtitleTracks.length){trackOption(s,'OFF',()=>selectSubtitle('OFF'));subtitleTracks.forEach((track,i)=>trackOption(s,track.name||track.lang||track.labels?.[0]?.text||'PISTA '+(i+1),()=>{if(instance!==engine)return;if(engineType==='hls'){instance.subtitleDisplay=true;instance.subtitleTrack=i}else {instance.enableText?.(true);if(instance.setTextTrack)instance.setTextTrack(i);else instance.setCurrentTrack?.(track)}}))}
 else if(video.textTracks?.length){trackOption(s,'OFF',()=>selectSubtitle('OFF'));for(let i=0;i<video.textTracks.length;i++){const track=video.textTracks[i];trackOption(s,track.label||track.language||'PISTA '+(i+1),()=>nativeSubtitle(i))}}
 else trackOption(s,'SIN PISTAS DE SUBTÍTULOS');
}
function selectAudio(){updateMenus()}
function selectSubtitle(value){if(value==='OFF'){if(engineType==='hls'&&engine){engine.subtitleDisplay=false;engine.subtitleTrack=-1}else if(engineType==='dash')engine?.enableText?.(false);nativeSubtitle(-1)}$('gu-live-sub-drop').style.display='none'}
function selectQuality(){updateMenus()}
const host=location.hostname||'LOCAL';$('gu-live-host-check').textContent='HOST: '+host;root.querySelectorAll('.gu-display-domain').forEach(e=>e.textContent=host);
// Editor original de título: edición, estilo, sombra, efectos, posición y cambio de tamaño.
const panel=$('gu-live-corel-panel'),ghost=$('gu-live-ghost-btn'),titleBox=$('gu-live-title-box');
function setEdit(on){editing=on;panel.classList.toggle('visible',on);ghost.classList.toggle('active',on);titleBox.classList.toggle('gu-editing-box',on);title.contentEditable='false';titleBox.tabIndex=on?0:-1;showUI()}
ghost.addEventListener('click',()=>setEdit(!editing));$('gu-live-close-corel').onclick=()=>setEdit(false);$('gu-live-save-btn').onclick=()=>setEdit(false);
function enableTitleTyping(){setEdit(true);title.contentEditable='true';title.focus();try{document.execCommand('selectAll',false,null)}catch{}}
title.addEventListener('dblclick',enableTitleTyping);titleBox.addEventListener('dblclick',e=>{if(e.target.closest('.gu-resize-handle'))return;enableTitleTyping()});title.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();title.blur()}if(e.key==='Escape')setEdit(false)});
$('gu-live-color-picker').oninput=e=>title.style.color=e.target.value;
$('gu-live-shadow-picker').oninput=e=>document.documentElement.style.setProperty('--gu-shadow-color',e.target.value);
$('gu-live-fx-select').onchange=e=>{title.className='gu-title gu-movie-title '+e.target.value};
let dragTitle=null;
title.addEventListener('blur',()=>{title.contentEditable='false'});
titleBox.addEventListener('pointerdown',e=>{if(!editing||e.target.classList.contains('gu-resize-handle')||title.contentEditable==='true')return;e.preventDefault();e.stopPropagation();dragTitle={x:e.clientX,y:e.clientY,tx:Number(titleBox.dataset.tx)||0,ty:Number(titleBox.dataset.ty)||0};titleBox.setPointerCapture(e.pointerId)});
titleBox.addEventListener('pointermove',e=>{if(!dragTitle)return;const x=dragTitle.tx+e.clientX-dragTitle.x,y=dragTitle.ty+e.clientY-dragTitle.y;titleBox.dataset.tx=x;titleBox.dataset.ty=y;titleBox.style.transform=`translate(${x}px,${y}px)`});
['pointerup','pointercancel','lostpointercapture'].forEach(type=>titleBox.addEventListener(type,()=>dragTitle=null));
titleBox.addEventListener('keydown',e=>{if(!editing||title.contentEditable==='true'||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const step=e.shiftKey?10:1,x=(Number(titleBox.dataset.tx)||0)+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),y=(Number(titleBox.dataset.ty)||0)+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0);titleBox.dataset.tx=x;titleBox.dataset.ty=y;titleBox.style.transform=`translate(${x}px,${y}px)`});
root.querySelectorAll('.gu-resize-handle').forEach(dot=>{let rs=null;dot.addEventListener('pointerdown',e=>{if(!editing)return;e.stopPropagation();rs={x:e.clientX,size:parseFloat(getComputedStyle(title).fontSize)};dot.setPointerCapture(e.pointerId)});dot.addEventListener('pointermove',e=>{if(rs)title.style.fontSize=Math.max(10,Math.min(120,rs.size+(e.clientX-rs.x)*.5))+'px'});for(const event of ['pointerup','pointercancel','lostpointercapture'])dot.addEventListener(event,()=>rs=null)});
// TYPO LOGO STUDIO PRO: 4 capas independientes, fuentes, gradientes, efectos y arrastre.
const stage=$('gu-live-typo-logo-stage'),layers=Array.from(stage.querySelectorAll('[data-typo-stage-layer]'));
const buttons=Array.from(root.querySelectorAll('[data-typo-layer]'));
const defaults=[{text:'GRAVITY ULTRA',x:18,y:30,size:74,visible:true},{text:'STUDIO',x:28,y:48,size:32,visible:false},{text:'X',x:42,y:26,size:90,visible:false},{text:'PRO',x:48,y:50,size:42,visible:false}].map(o=>({...o,font:'Montserrat',style:'gradient',colors:['#ff0033','#00e5ff','#ffd54a','#ffffff','#6c43ff','#111111'],rotation:0,spacing:3,skew:0,depth:6,glow:8,outline:1,angle:90,opacity:10}));
let states=defaults.map(x=>structuredClone(x)),active=0,logoVisible=false;
const fonts=["Montserrat", "Playfair Display", "Lato", "Poppins", "Roboto Slab", "Roboto", "Cormorant Garamond", "Oswald", "Fjalla One", "Prata", "Bodoni Moda", "Didact Gothic", "Inter", "Merriweather", "Nunito", "Raleway", "Ubuntu", "Cabin", "Comfortaa", "Josefin Sans", "Kanit", "Quicksand", "Space Grotesk", "Titillium Web", "Cinzel", "Cinzel Decorative", "Bebas Neue", "Anton", "Macondo", "Orbitron", "Creepster", "Nosifer", "Butcherman", "Eater", "Abril Fatface", "Pacifico", "Dancing Script", "Caveat", "Shojumaru", "Ma Shan Zheng", "Zhi Mang Xing", "UnifrakturMaguntia", "MedievalSharp", "Righteous", "Syncopate", "Teko", "Bangers", "Permanent Marker", "Amatic SC", "Alfa Slab One", "Archivo Black", "Gloria Hallelujah", "Great Vibes", "Indie Flower", "Satisfy", "Shadows Into Light", "Tangerine", "Fredoka One", "Press Start 2P", "Chewy", "Audiowide", "Russo One", "Bungee", "Bungee Shade", "Luckiest Guy", "Comic Neue", "Carter One", "Boogaloo", "VT323", "Rampart One", "Rubik Bubbles", "Reggae One", "ZCOOL KuaiLe", "Racing Sans One", "Black Ops One", "Fascinate Inline", "Lobster", "Leckerli One", "Fuzzy Bubbles", "Spicy Rice", "Wallpoet", "Akronim", "Baloo 2", "Bowlby One SC", "Changa One", "Chicle", "Concert One", "DotGothic16", "Frijole", "Grenze Gotisch", "Hachi Maru Pop", "Henny Penny", "Irish Grover", "Jolly Lodger", "Kalam", "Kaushan Script", "Knewave", "Lilita One", "Londrina Solid", "M PLUS Rounded 1c", "Monofett", "New Rocker", "Odibee Sans", "Oxanium", "Patrick Hand SC", "Paytone One", "Rubik Mono One", "Sarpanch", "Sedgwick Ave Display", "Sigmar", "Silkscreen", "Staatliches", "Stick", "Train One", "Yusei Magic", "Zen Tokyo Zoo"];
const fontSelect=$('gu-logo-font-select');fonts.forEach(f=>{const o=document.createElement('option');o.value=f;o.textContent=f.toUpperCase();fontSelect.appendChild(o)});$('gu-logo-font-count').textContent=fonts.length+' FUENTES';
function drawLogo(i){const s=states[i],el=layers[i],txt=el.querySelector('.gu-typo-logo-text');el.style.left=s.x+'%';el.style.top=s.y+'%';el.style.transform=`rotate(${s.rotation}deg) skewX(${s.skew}deg)`;el.style.opacity=s.opacity/10;el.classList.toggle('visible',logoVisible&&s.visible);el.classList.toggle('active',logoVisible&&active===i);
 txt.textContent=s.text||' ';txt.style.fontFamily=`'${s.font}',sans-serif`;txt.style.fontSize=s.size+'px';txt.style.letterSpacing=s.spacing+'px';txt.style.webkitTextStroke=s.outline+'px '+s.colors[5];txt.style.textShadow=Array.from({length:Math.min(s.depth,24)},(_,i)=>`${i+1}px ${i+1}px 0 ${s.colors[5]}`).concat([`0 0 ${s.glow}px ${s.colors[0]}`]).join(',');txt.style.background='none';txt.style.color=s.colors[0];txt.style.webkitTextFillColor='initial';txt.style.filter='';
 if(['gradient','metal','glass'].includes(s.style)){let cs=s.style==='metal'?[s.colors[3],s.colors[0],s.colors[2],s.colors[1],s.colors[3]]:s.style==='glass'?['#fff',s.colors[0],'#ccc',s.colors[1]]:s.colors;txt.style.background=`linear-gradient(${s.angle}deg,${cs.join(',')})`;txt.style.webkitBackgroundClip='text';txt.style.backgroundClip='text';txt.style.webkitTextFillColor='transparent'}
 if(s.style==='neon'){txt.style.color='#fff';txt.style.textShadow=`0 0 3px #fff,0 0 ${s.glow}px ${s.colors[0]},0 0 ${s.glow*2}px ${s.colors[1]}`}}
function syncLogo(){const s=states[active];$('gu-logo-name-input').value=s.text;fontSelect.value=s.font;$('gu-logo-style-select').value=s.style;root.querySelectorAll('[data-logo-color]').forEach((el,i)=>el.value=s.colors[i]);['size','rotation','spacing','skew','depth','glow','outline','angle','opacity'].forEach(k=>{const el=$('gu-logo-'+k),out=$('gu-logo-'+k+'-val');el.value=s[k];out.textContent=k==='opacity'?s[k]*10+'%':s[k]+(['rotation','skew','angle'].includes(k)?'°':'')});buttons.forEach((b,i)=>b.classList.toggle('active',i===active))}
let guTypoReference={width:1280,height:720};
function guRememberTypoReference(){if(!document.body.classList.contains('gu-ve-active')&&root.clientWidth&&root.clientHeight)guTypoReference={width:root.clientWidth,height:root.clientHeight}}
function drawAll(){guRememberTypoReference();layers.forEach((_,i)=>drawLogo(i));syncLogo()}
function choose(i){active=i;states[i].visible=true;logoVisible=true;drawAll()}
buttons.forEach((b,i)=>b.onclick=()=>choose(i));
$('gu-logo-toggle').onclick=()=>{logoVisible=!logoVisible;states[active].visible=true;$('gu-logo-toggle').textContent=logoVisible?'OCULTAR LOGO':'MOSTRAR LOGO';drawAll()};
$('gu-logo-reset').onclick=()=>{states=defaults.map(x=>structuredClone(x));active=0;logoVisible=true;$('gu-logo-toggle').textContent='OCULTAR LOGO';drawAll()};
$('gu-logo-name-input').oninput=e=>{states[active].text=e.target.value;logoVisible=true;drawAll()};fontSelect.onchange=e=>{states[active].font=e.target.value;drawAll()};$('gu-logo-style-select').onchange=e=>{states[active].style=e.target.value;drawAll()};
root.querySelectorAll('[data-logo-color]').forEach((el,i)=>el.oninput=e=>{states[active].colors[i]=e.target.value;drawAll()});
['size','rotation','spacing','skew','depth','glow','outline','angle','opacity'].forEach(k=>{$('gu-logo-'+k).oninput=e=>{states[active][k]=Number(e.target.value);drawAll()}});
layers.forEach((el,i)=>{let d=null;el.addEventListener('pointerdown',e=>{if(e.target.classList.contains('gu-typo-resize-dot'))return;choose(i);d={x:e.clientX,y:e.clientY,left:states[i].x,top:states[i].y};el.setPointerCapture(e.pointerId);e.preventDefault()});el.addEventListener('pointermove',e=>{if(!d)return;const r=root.getBoundingClientRect();states[i].x=Math.max(0,Math.min(92,d.left+(e.clientX-d.x)/r.width*100));states[i].y=Math.max(0,Math.min(88,d.top+(e.clientY-d.y)/r.height*100));drawLogo(i)});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,()=>d=null);const dot=el.querySelector('.gu-typo-resize-dot');let rs=null;dot.addEventListener('pointerdown',e=>{e.stopPropagation();choose(i);rs={x:e.clientX,size:states[i].size};dot.setPointerCapture(e.pointerId)});dot.addEventListener('pointermove',e=>{if(rs){states[i].size=Math.max(20,Math.min(220,rs.size+(e.clientX-rs.x)*.6));drawAll()}});for(const event of ['pointerup','pointercancel','lostpointercapture'])dot.addEventListener(event,()=>rs=null)});
drawAll();
window.guTypoStudio={
 getSnapshot:()=>({visible:logoVisible,referenceWidth:guTypoReference.width,referenceHeight:guTypoReference.height,layers:structuredClone(states)}),
 getFonts:()=>fonts.slice()
};
if(typeof ResizeObserver==='function')new ResizeObserver(guRememberTypoReference).observe(root);
// La carga inicial espera los scripts defer; los archivos locales no necesitan librerías.
function initializePlayerSource(){
 try{let src=p.get('video')||p.get('src');if(!src&&p.get('v'))src=atob(p.get('v'));if(p.get('title'))title.textContent=p.get('title');else if(p.get('t')){try{title.textContent=decodeURIComponent(atob(p.get('t')))}catch{}}if(src)setSource(src);if(p.get('tags'))tags.textContent=p.get('tags');if(p.get('c')){try{guSetColor(null,atob(p.get('c')))}catch{}}}catch(error){console.warn('Parámetros no válidos',error)}
 updateMenus();update();syncVolume();
}
for(const el of root.querySelectorAll('[onclick],#gu-live-btn-play,#gu-live-btn-mute,#gu-live-btn-fullscreen,#gu-live-ghost-btn,[data-typo-layer]'))accessibleControl(el);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initializePlayerSource,{once:true});else initializePlayerSource();
})();
